// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · Sosyoloji temel kavramları ve toplumsal kurumlar (orta).
const ozSocialscience1Orta = <(String, String, List<String>, String)>[
  ('Aşağıdaki araştırma sorularından hangisi doğrudan sosyolojinin ilgi alanına girer?', 'Kırdan kente göç eden ailelerde akrabalık bağları nasıl değişiyor?', ['Uzun süreli stres bağışıklık sistemini nasıl etkiliyor?', 'Anadolu\'daki fay hatları hangi yönde uzanıyor?', 'Bir ilacın kandaki yarılanma süresi ne kadardır?'], 'Göç ve akrabalık bağlarındaki değişim, toplumsal ilişkiler ve kurumlarla ilgili olduğundan sosyolojinin konusudur.'),
  ('Mikro sosyolojinin odaklandığı konuya en uygun örnek hangisidir?', 'Bir otobüste yolcuların göz teması kurma biçimleri', ['Küresel ticaretin ülkeler arası eşitsizliğe etkisi', 'Nüfusun yaş yapısının uzun dönemli değişimi', 'Eğitim sisteminin ekonomik kalkınmadaki rolü'], 'Mikro sosyoloji küçük ölçekli, yüz yüze etkileşimleri inceler; otobüsteki yolcuların davranışları bunun tipik örneğidir.'),
  ('Fransız İhtilali\'nin sosyolojik düşünceyi etkilemesinin temel nedeni hangisidir?', 'Geleneksel düzen ve otoritenin çözülmesiyle toplumsal düzen sorununu gündeme getirmesi', ['Avrupa\'da yeni bir mezhebin kurulmasını sağlaması', 'Sanayi üretimini başlatması', 'Kırsal nüfusu kentlere göre artırması'], 'İhtilal, monarşi, aristokrasi ve kilise etrafında kurulmuş eski düzeni sarstı; düşünürler yeni düzenin nasıl kurulacağını sorgulamaya başladı.'),
  ('Auguste Comte sosyoloji teriminden önce toplum bilimini adlandırmak için hangi terimi kullanmıştı?', 'Sosyal fizik', ['Toplumsal kimya', 'İnsan coğrafyası', 'Ahlak bilimi'], 'Comte toplum bilimine önce "sosyal fizik" adını vermiş, bu terim Quetelet tarafından da kullanılınca "sosyoloji" terimini önermiştir.'),
  ('Auguste Comte\'un üç hal yasasına göre insan düşüncesinin geçtiği aşamalar hangi sırayla verilmiştir?', 'Teolojik, metafizik, pozitif', ['Metafizik, teolojik, pozitif', 'Pozitif, teolojik, metafizik', 'Teolojik, pozitif ve metafizik'], 'Comte\'a göre düşünce önce olayları doğaüstü güçlerle (teolojik), sonra soyut ilkelerle (metafizik), en sonunda gözlem ve deneyle (pozitif) açıklar.'),
  ('Bir düşünürün olayları "doğanın özü" ya da "yaşam gücü" gibi gözlemlenemeyen soyut kavramlarla açıklaması, Comte\'a göre hangi aşamanın göstergesidir?', 'Metafizik aşama', ['Teolojik aşama', 'Pozitif aşama', 'Askeri (militer) aşama'], 'Metafizik aşamada doğaüstü varlıkların yerini soyut güçler ve özler alır; açıklamalar hâlâ gözlem ve deneye dayanmaz.'),
  ('Comte sosyolojiyi "toplumsal statik" ve "toplumsal dinamik" olarak ikiye ayırmıştır. Toplumsal statik neyi inceler?', 'Toplumun düzenini ve onu ayakta tutan yapıları', ['Toplumların tarihsel ilerleyişini ve değişimini', 'Bireylerin kişilik gelişimini', 'Nüfusun coğrafi dağılımını'], 'Toplumsal statik toplumsal düzeni ve yapıları; toplumsal dinamik ise toplumların gelişimini ve değişmesini inceler.'),
  ('Comte\'un, toplumların incelenmesinde gözlem, deney ve karşılaştırma gibi yöntemlerin kullanılmasını savunması hangi anlayışı temsil eder?', 'Pozitivist anlayışı', ['Tarihsel materyalizmi', 'Anlayıcı sosyolojiyi', 'Sembolik etkileşimciliği'], 'Comte, bilgi edinmenin tek güvenilir yolunun gözlem ve deneye dayalı pozitif yöntem olduğunu savunmuş ve pozitivizmin kurucusu kabul edilmiştir.'),
  ('Durkheim\'ın, intihar oranlarının toplumsal bütünleşme düzeyiyle ilişkisini istatistiklerle incelediği eseri hangisidir?', 'İntihar', ['Protestan Ahlakı ve Kapitalizmin Ruhu', 'Kapital', 'Mukaddime'], 'Durkheim 1897\'de yayımlanan İntihar adlı eserinde, bireysel görünen bir davranışın toplumsal nedenlere bağlı olarak farklı oranlarda görüldüğünü göstermiştir.'),
  ('Hızlı bir ekonomik çöküşün ardından toplumu düzenleyen kuralların gevşemesiyle artan intiharları Durkheim hangi türe yerleştirir?', 'Anomik intihar', ['Diğerkâm intihar', 'Egoist intihar', 'Kadercil intihar'], 'Anomik intihar, ani toplumsal değişmelerde normların zayıfladığı ya da belirsizleştiği durumlarda ortaya çıkar.'),
  ('Durkheim\'ın egoist intihar türünü açıklarken vurguladığı toplumsal koşul hangisidir?', 'Bireyin gruba bağlılığının çok zayıf olması', ['Toplumsal kuralların çok katı olması', 'Ekonomik refahın birden ve beklenmedik biçimde artması', 'Bireyin gruba aşırı bağlanması'], 'Egoist intihar, bireyin aile, din ya da topluluk gibi gruplarla bağlarının zayıfladığı, yalnızlaştığı durumlarda görülür.'),
  ('Durkheim\'ın toplumun üyelerince paylaşılan inanç ve duyguların bütününü anlatmak için kullandığı kavram hangisidir?', 'Kolektif bilinç', ['Sınıf bilinci', 'Ayna benlik', 'Habitus'], 'Kolektif bilinç, bir toplumun ortalama üyelerinde ortak olan inanç ve duyguların, bireyleri aşan bütünüdür.'),
  ('Durkheim, toplumsal işbölümünü ve dayanışma türlerini hangi eserinde ele almıştır?', 'Toplumsal İşbölümü Üzerine', ['Ekonomi ve Toplum', 'Pozitif Felsefe Dersleri', 'Toplumun Kuruluşu'], 'Durkheim 1893 tarihli Toplumsal İşbölümü Üzerine adlı doktora tezinde mekanik ve organik dayanışmayı karşılaştırmıştır.'),
  ('Weber\'in sosyolojik yöntemde kullandığı, gerçekliğin belirgin özelliklerinin vurgulanmasıyla kurulan soyut model hangisidir?', 'İdeal tip', ['Kolektif bilinç', 'Toplumsal olgu', 'Diyalektik'], 'İdeal tip, araştırmacının gerçek durumları karşılaştırmak için olgunun tipik özelliklerini abartarak oluşturduğu kavramsal bir ölçüttür.'),
  ('Bir öğrencinin yüksek not almak için en verimli çalışma yöntemini hesaplayıp seçmesi, Weber\'in eylem türlerinden hangisine örnektir?', 'Amaçsal-rasyonel eylem', ['Geleneksel eylem', 'Duygusal eylem', 'Değer-rasyonel (değere yönelik) eylem'], 'Amaçsal-rasyonel eylemde birey belirli bir amaca ulaşmak için en etkili araçları hesaplayarak seçer.'),
  ('Bir kişinin hiçbir çıkar gözetmeden, yalnızca dürüstlüğe inandığı için kendisine zarar verecek bir gerçeği açıklaması, Weber\'e göre hangi eylem türüdür?', 'Değer-rasyonel eylem', ['Amaçsal-rasyonel eylem', 'Geleneksel eylem', 'Duygusal eylem'], 'Değer-rasyonel eylem, sonucu ne olursa olsun bir değere ya da ilkeye bağlılıkla yapılan eylemdir.'),
  ('Bir ailenin "Atalarımızdan böyle gördük" diyerek bayram sabahı her yıl aynı sırayla akrabaları ziyaret etmesi, Weber\'e göre hangi eylem türüdür?', 'Geleneksel eylem', ['Duygusal eylem', 'Amaçsal-rasyonel eylem', 'Değer-rasyonel eylem'], 'Geleneksel eylem, alışkanlık ve süregelen geleneklerle, üzerinde çok düşünülmeden yapılan eylemdir.'),
  ('Weber\'in toplumsal tabakalaşmayı yalnızca ekonomik temele indirgemeyip ele aldığı üç boyut hangisidir?', 'Sınıf, statü ve parti (iktidar)', ['Kast, zümre ve toplumsal sınıf (köken)', 'Gelir, nüfus ve kent', 'Din, dil ve ırk'], 'Weber tabakalaşmayı ekonomik konum (sınıf), toplumsal saygınlık (statü) ve siyasal güç (parti) boyutlarıyla açıklar.'),
  ('Marx\'ın "yabancılaşma" kavramı kapitalist üretimde işçinin hangi durumunu anlatır?', 'Ürettiği ürüne, emeğine ve kendi özüne yabancı düşmesini', ['Başka bir ülkeye göç ederek kültür değiştirmesini', 'Kendi sınıfından daha üst bir sınıfa geçmesini', 'Toplumsal kurallara uymayı reddetmesini'], 'Marx\'a göre işçi ürettiği ürün üzerinde söz sahibi olmadığından emeğine, ürününe, diğer insanlara ve kendi insani özüne yabancılaşır.'),
  ('İbn Haldun\'un toplumsal olayları incelediği bilime verdiği ad hangisidir?', 'İlm-i umran', ['İlm-i kelam', 'İlm-i hey\'et', 'İlm-i siyer'], 'İbn Haldun toplum bilimine "ilm-i umran" (umran ilmi) adını vermiştir; umran insan topluluğu ve toplumsal yaşam demektir.'),
  ('Le Play okulundan etkilenen ve Türk toplumunun kalkınması için bireysel girişim ile adem-i merkeziyeti savunan Osmanlı aydını kimdir?', 'Prens Sabahattin', ['Ziya Gökalp', 'Mehmed Ali Şevki', 'Hilmi Ziya Ülken'], 'Prens Sabahattin, toplumları cemaatçi ve bireyci (teşebbüs-i şahsi) olarak ayırmış ve Türk toplumunun bireyci yapıya geçmesi gerektiğini savunmuştur.'),
  ('1960\'larda yayımlanan "Ereğli: Ağır Sanayiden Önce Bir Sahil Kasabası" adlı monografisiyle tanınan Türk sosyolog kimdir?', 'Mübeccel Kıray', ['Ziya Gökalp', 'Prens Sabahattin', 'Nurettin Topçu'], 'Mübeccel Kıray, Ereğli monografisi ve toplumsal değişme üzerine çalışmalarıyla Türk sosyolojisinde alan araştırmasının öncülerindendir.'),
  ('İstanbul Darülfünunu\'nda ilk sosyoloji (içtimaiyat) kürsüsü hangi yıl kurulmuştur?', '1914', ['1863 yılı', '1933', '1923'], 'İçtimaiyat kürsüsü 1914\'te kurulmuş ve ilk hocası Ziya Gökalp olmuştur.'),
  ('"Kentlerde yaşayan gençlerin evlilik yaşı köylerdekilere göre daha yüksektir." Bu ifade bir araştırmanın hangi aşamasına aittir?', 'Hipotez', ['Bulgu', 'Kaynakça', 'Gözlem formu'], 'Hipotez, araştırma ile sınanacak, değişkenler arasındaki ilişkiyi öngören geçici bir açıklamadır.'),
  ('Nitel araştırma ile nicel araştırmayı ayıran temel özellik hangisidir?', 'Nicel araştırmanın sayısal verilerle ölçüm, nitelin anlam ve derinlik arayışı', ['Nicelin yalnız eski belgelere, nitelin yalnız anketlere dayanması', 'Nitelin her zaman daha geniş örneklem kullanması', 'Nicelin araştırmacının görüşlerine dayanması'], 'Nicel araştırma ölçme ve istatistiğe dayanır; nitel araştırma görüşme ve gözlemle olguların anlamını derinlemesine anlamaya çalışır.'),
  ('Bir araştırmacı, 1950-1980 arası yerel gazetelerdeki evlilik ilanlarını inceleyerek eş seçimindeki değişimi araştırıyor. Kullandığı teknik hangisidir?', 'Belge (doküman) incelemesi', ['Katılımlı gözlem ve alan notları', 'Yüz yüze görüşme', 'Deney'], 'Gazete, arşiv kaydı, mektup gibi yazılı kaynakların çözümlenmesi belge incelemesi tekniğidir.'),
  ('Sosyolojide laboratuvar deneyinin az kullanılmasının en önemli nedeni hangisidir?', 'Toplumsal olayların tüm değişkenleriyle denetimli ortamda yeniden kurulamaması', ['Sosyologların istatistik bilgisinin olmaması', 'Toplumsal olayların gözlenememesi', 'Deneyin her zaman pahalı olması'], 'Toplumsal olaylar çok sayıda etkenin bir arada bulunduğu doğal ortamlarda oluşur; bunları laboratuvarda denetimli biçimde kurmak çoğu zaman olanaksız ve etik dışıdır.'),
  ('Toplumsal yaşamı bireylerin semboller, özellikle dil aracılığıyla kurduğu anlamlar üzerinden açıklayan mikro yaklaşım hangisidir?', 'Sembolik etkileşimcilik', ['Yapısal işlevselcilik', 'Çatışma kuramı', 'Dünya sistemleri kuramı ve analizi'], 'Sembolik etkileşimcilik, insanların nesnelere ve olaylara yükledikleri anlamların etkileşim içinde oluştuğunu savunur; G. H. Mead ve H. Blumer öncü adlarıdır.'),
  ('Bir sosyolog, okul sisteminin varlıklı ailelerin çocuklarını daha iyi işlere taşıyarak eşitsizliği yeniden ürettiğini savunuyor. Bu görüş hangi kuramsal yaklaşıma daha yakındır?', 'Çatışma kuramı', ['Yapısal işlevselcilik', 'Sembolik etkileşimcilik', 'Evrimci kuram'], 'Eğitimin eşitsizliği yeniden ürettiği görüşü, toplumsal kurumların egemen grupların çıkarına hizmet ettiğini savunan çatışma kuramına dayanır.'),
  ('Robert Merton\'un "açık işlev" ve "örtük işlev" ayrımında örtük işlev neyi ifade eder?', 'Bir kurumun amaçlanmamış ve çoğu zaman fark edilmeyen sonuçlarını', ['Bir kurumun resmi olarak ilan edilmiş amacını', 'Toplumsal düzeni bozan sonuçları', 'Yasalarla tanımlanmış görevleri'], 'Açık işlev amaçlanan ve bilinen sonuç; örtük işlev ise amaçlanmamış, fark edilmeyen sonuçtur. Örneğin üniversitelerin eş bulma ortamı olması örtük bir işlevdir.'),
  ('Sembolik etkileşimciliğe yöneltilen eleştirilerden biri hangisidir?', 'Büyük toplumsal yapıları ve güç ilişkilerini yeterince açıklayamaması', ['Yüz yüze ilişkileri hiç incelememesi', 'Bireyleri tamamen pasif varlıklar olarak görmesi', 'Yalnızca sayısal verilere dayanması'], 'Mikro düzeyde etkileşime odaklanan bu yaklaşım, ekonomik yapı ve kurumsal güç gibi makro etkenleri ihmal ettiği gerekçesiyle eleştirilir.'),
  ('Herbert Spencer\'ın toplumları canlı bir organizmaya benzeterek açıklayan görüşü hangi adla anılır?', 'Organisizm', ['Diyalektik materyalizm', 'Sembolik etkileşimcilik', 'Etnometodoloji'], 'Spencer toplumun da canlılar gibi büyüyüp farklılaştığını, parçalarının organlar gibi birbirine bağlı işlev gördüğünü savunmuştur.'),
  ('Toplumları "Gemeinschaft" (cemaat) ve "Gesellschaft" (cemiyet) olarak ikiye ayıran Alman sosyolog kimdir?', 'Ferdinand Tönnies', ['Georg Simmel', 'Max Weber', 'Norbert Elias'], 'Tönnies 1887\'de yayımlanan Cemaat ve Cemiyet adlı eserinde iki toplum tipini birbirinden ayırmıştır.'),
  ('İnsanların birbirini yakından tanıdığı, ilişkilerin duygusal ve geleneksel bağlara dayandığı küçük bir köy, Tönnies\'e göre hangi tipe girer?', 'Cemaat (Gemeinschaft)', ['Cemiyet (Gesellschaft)', 'Kitle toplumu', 'Sanayi sonrası toplum'], 'Cemaat tipi topluluklarda ilişkiler kişisel, yakın ve geleneğe dayalıdır; aile ve köy bunun tipik örnekleridir.'),
  ('Tönnies\'in "cemiyet" tipi toplumunda ilişkilerin belirgin özelliği hangisidir?', 'Çıkar ve sözleşmeye dayalı, kişisel olmayan ilişkiler', ['Akrabalık bağlarının belirleyici olduğu yakın ilişkiler', 'Herkesin herkesi tanıdığı yüz yüze ilişkiler', 'Ortak inançlara bağlı kutsal ilişkiler'], 'Cemiyette ilişkiler bireysel çıkar, hesap ve sözleşmeye dayanır; büyük kentler bu tipin örneğidir.'),
  ('Avcı-toplayıcı toplumların temel özelliği hangisidir?', 'Besinlerini doğadan doğrudan sağlayan küçük, göçebe gruplar olmaları', ['Geniş topraklarda saban tarımı yapan yerleşik köyler kurmaları', 'Fabrikalarda ücretli emeğe dayanan üretim yapmaları', 'Bilgi ve hizmet üretimini ekonominin merkezine koymaları'], 'Avcı-toplayıcılar yiyeceklerini avlanarak ve bitki toplayarak elde eder; genellikle küçük ve hareketli gruplar halinde yaşarlar.'),
  ('Tarım toplumuna geçişin toplumsal yapı üzerindeki en önemli sonucu hangisidir?', 'Yerleşik yaşam, artı ürün ve buna bağlı olarak tabakalaşmanın belirginleşmesi', ['İnsanların göçebe yaşama dönmesi ve mülkiyetin ortadan kalkması', 'Ücretli fabrika emeğinin yaygınlaşması', 'Bilgi teknolojilerinin ekonomide belirleyici olması'], 'Tarımla birlikte yerleşik yaşam, artı ürün ve toprak mülkiyeti ortaya çıkmış; bu da eşitsizlik ve tabakalaşmayı belirgin hale getirmiştir.'),
  ('Daniel Bell\'in kullandığı "sanayi sonrası toplum" kavramına göre bu toplumlarda ekonominin ağırlık merkezi nereye kaymıştır?', 'Hizmet ve bilgi üretimine', ['Avcılık ve toplayıcılığa', 'Hayvancılık ve göçebeliğe', 'Ağır sanayi ve madenciliğe'], 'Bell\'e göre sanayi sonrası toplumda istihdamın büyük kısmı hizmet sektöründedir ve kuramsal bilgi temel kaynak haline gelir.'),
  ('Durkheim\'a göre benzerliklere, ortak inanç ve değerlere dayanan dayanışma türü hangisidir?', 'Mekanik dayanışma', ['Organik dayanışma', 'Sözleşmeye dayalı dayanışma', 'Sınıf dayanışması'], 'Mekanik dayanışmada bireyler birbirine benzer işler yapar, aynı inançları paylaşır; bütünleşme benzerlikten doğar.'),
  ('Toplumsal yapının hangi özelliği onu bir binanın iskeletine benzetmeyi mümkün kılar?', 'Görece kalıcı olması ve öğelerinin birbirine bağlı olması', ['Her gün tamamen değişmesi', 'Yalnız tek bir kurumdan oluşması', 'Bireylerin iradesinden hiç etkilenmemesi'], 'Toplumsal yapı yavaş değişen, öğeleri birbirine bağlı bir bütündür; bu nedenle toplumsal yaşamın iskeleti olarak düşünülür.'),
  ('Geleneksel Türk köyünde aileler arasındaki dayanışmayla yapılan, örneğin ekin biçme ya da ev yapma gibi ortak çalışmalara ne ad verilir?', 'İmece', ['Muhtarlık', 'Hısımlık', 'Lonca'], 'İmece, köy halkının bir kişinin ya da topluluğun işini karşılıksız olarak birlikte yapmasıdır; mekanik dayanışmanın tipik örneğidir.'),
  ('Bir toplumda kazanılmış statülerin önem kazanması genellikle hangi toplumsal dönüşümle ilişkilidir?', 'Sanayileşme ve modernleşmeyle', ['Kast sisteminin güçlenmesiyle', 'Feodal düzenin yaygınlaşmasıyla', 'Avcı-toplayıcılığa dönüşle'], 'Modern toplumlarda eğitim ve meslek gibi çabayla elde edilen konumlar, soy ve doğuştan gelen özelliklere göre daha belirleyici hale gelir.'),
  ('Bir öğretmenin hem öğrencilerine yakın davranması hem de onlar üzerinde otorite kurması gerektiği için zorlanması hangi kavramla açıklanır?', 'Rol gerilimi', ['Rol çatışması', 'Statü kümesi', 'Rol farklılaşması'], 'Rol gerilimi, tek bir statüye bağlı rolün içindeki çelişkili beklentilerden kaynaklanır; rol çatışmasında ise farklı statüler söz konusudur.'),
  ('Bir garsonun müşterilerin yanında güler yüzlü ve resmi, mutfakta ise şakacı ve rahat davranması Goffman\'ın hangi kavramlarıyla açıklanır?', 'Ön sahne ve kulis', ['Altyapı ve üstyapı', 'Cemaat ve cemiyet', 'Mekanik ve organik dayanışma'], 'Goffman\'ın dramaturjik yaklaşımına göre garson müşteri önünde (ön sahne) rolünü sergiler, mutfakta (kulis) daha rahat davranır.'),
  ('Rollerin toplumsal yaşamdaki temel işlevi hangisidir?', 'Karşılıklı beklentileri belirleyerek davranışları öngörülebilir kılmak', ['Bireylerin bütün davranışlarını tek tipleştirmek', 'Toplumsal değişmeyi tamamen engellemek', 'Statülerin ortadan kalkmasını sağlamak'], 'Roller sayesinde insanlar birbirlerinden ne bekleyeceklerini bilir; bu da toplumsal etkileşimi düzenli ve öngörülebilir hale getirir.'),
  ('"Birincil grup" kavramını sosyolojiye kazandıran Amerikalı sosyolog kimdir?', 'Charles H. Cooley', ['George H. Mead', 'Talcott Parsons', 'Robert Park'], 'Cooley, 1909 tarihli Toplumsal Örgütlenme adlı eserinde aile ve oyun grubu gibi yakın grupları birincil grup olarak adlandırmıştır.'),
  ('İkincil grupların birincil gruplardan ayrılan temel özelliği hangisidir?', 'Belirli bir amaca yönelik, resmi ve kişisel olmayan ilişkiler içermesi', ['Duygusal ve kalıcı yakınlık bağları üzerine kurulması', 'Yalnızca akrabalardan oluşması', 'Üyelerin birbirini çocukluktan tanıması'], 'İkincil gruplarda ilişkiler amaca dönük ve resmidir; üyeler birbirini bütün kişiliğiyle değil, belirli rolleriyle tanır.'),
  ('Bir öğrencinin kendini hiç üyesi olmadığı ünlü bir müzik grubunun hayranlarıyla özdeşleştirip giyim ve konuşmasını onlara göre ayarlaması hangi kavramla açıklanır?', 'Referans (danışma) grubu', ['Birincil grup', 'Toplumsal kategori', 'Kalabalık'], 'Referans grubu, bireyin üyesi olsun ya da olmasın, davranışlarını ve değerlendirmelerini kendisine göre ayarladığı gruptur.'),
  ('Bir üniversitede kurulan, yazılı tüzüğü, yönetim kurulu ve seçimle belirlenen başkanı olan öğrenci kulübü hangi grup türüne girer?', 'Resmi (biçimsel) grup', ['Birincil grup', 'Toplumsal kategori', 'Kalabalık'], 'Kuralları yazılı, görev dağılımı belirgin ve örgütlü yapıdaki gruplar resmi gruplardır.'),
  ('Bir grubun büyüklüğü arttıkça genellikle hangi değişim görülür?', 'İlişkiler resmileşir ve kurallara olan ihtiyaç artar', ['Üyeler arasındaki duygusal yakınlık her zaman daha da güçlenir', 'Grubun örgütlenmeye hiç gereksinimi kalmaz', 'Bütün üyeler birbirini yakından tanır'], 'Grup büyüdükçe yüz yüze ilişkiler azalır, işbölümü ve yazılı kurallar gibi resmi düzenlemeler önem kazanır.'),
  ('Toplumsal kategorinin toplumsal gruptan ayrılan temel özelliği hangisidir?', 'Üyeler arasında süreklilik gösteren bir etkileşim ve örgütlenme bulunmaması', ['Üyelerin tamamen aynı mesleği yapması', 'Üyelerin yasalarla bir araya getirilmesi', 'Üyelerin aynı aileden gelmesi'], 'Kategori üyeleri ortak bir özelliği paylaşır ama birbirleriyle ilişki kurmaz ve bir biz duygusu oluşturmaz.'),
  ('Rekabeti çatışmadan ayıran temel özellik hangisidir?', 'Rekabette amacın rakibi yok etmek değil, kurallar içinde öne geçmek olması', ['Rekabette tarafların ortak bir amaç için birlikte çalışması', 'Rekabetin yalnızca ekonomik alanda görülmesi', 'Rekabette kuralların hiç bulunmaması ve şiddet içermesi'], 'Rekabet aynı amaca ulaşmak isteyenlerin kurallar çerçevesinde yarışmasıdır; çatışmada ise taraflar birbirini etkisiz kılmaya yönelir.'),
  ('Uzun süre birbiriyle anlaşmazlık yaşayan iki köyün, bir hakem heyetinin aracılığıyla otlak kullanımında bir düzen üzerinde anlaşması hangi sürecin örneğidir?', 'Uzlaşma', ['Rekabet', 'Asimilasyon', 'Çatışma'], 'Uzlaşma, tarafların karşılıklı ödünlerle anlaşmazlığı geçici ya da kalıcı biçimde sona erdirmesidir.'),
  ('Bir göçmen grubun zaman içinde kendi dilini ve geleneklerini bırakıp yaşadığı toplumun kültürüne tamamen karışması hangi süreçtir?', 'Asimilasyon', ['Uyum', 'Kültürel yayılma', 'Rekabet'], 'Asimilasyonda bir grup kendi kültürel özelliklerini yitirerek başka bir kültürün içinde erir; uyumda ise kültürel kimlik korunarak yeni ortama ayak uydurulur.'),
  ('Değerler ile normlar arasındaki ilişki en iyi hangi seçenekte açıklanmıştır?', 'Normlar, değerlerin günlük davranışlara dönüşmüş somut kurallarıdır', ['Değerler, normların yazılı olarak cezalandırılmış biçimidir', 'Normlar ve değerler birbiriyle hiç ilgisizdir', 'Değerler yalnızca bireylere özgü, normlar topluma özgüdür'], 'Örneğin "yaşlılara saygı" bir değerdir; "otobüste yaşlılara yer vermek" ise bu değerden doğan bir normdur.'),
  ('Bir kişinin kimse görmezken bile yerde bulduğu cüzdanı sahibine ulaştırması, büyük ölçüde hangisinin içselleştirildiğini gösterir?', 'Dürüstlük değerinin', ['Moda olgusunun', 'Bir hukuk kuralının yalnızca korkuyla uygulanmasının', 'Bir rol çatışmasının'], 'Dış denetim olmadan değere uygun davranmak, o değerin birey tarafından içselleştirildiğini gösterir.'),
  ('Yeni doğan bebeğin kulağına ezan okunarak ad konulması geleneği, kuşaktan kuşağa aktarılan bir davranış kuralı olarak hangi kavramla açıklanır?', 'Gelenek', ['Moda', 'Hukuk kuralı', 'Etik kod'], 'Gelenek, geçmişten gelen ve kuşaktan kuşağa aktarılarak sürdürülen davranış kalıplarıdır.'),
  ('Komşularının ayıplayacağı korkusuyla bir kişinin gece geç saatte yüksek sesle müzik dinlemekten vazgeçmesi hangi tür toplumsal kontrole örnektir?', 'Resmi olmayan (enformel) kontrol', ['Resmi (formel) kontrol ve yasal ceza', 'Yasal yaptırım', 'Kurumsal ceza'], 'Ayıplanma, dışlanma ve dedikodu gibi tepkiler resmi olmayan toplumsal kontrol araçlarıdır.'),
  ('Sapma ile suç arasındaki ilişki en doğru hangi seçenekte verilmiştir?', 'Her suç bir sapmadır, ama her sapma suç değildir', ['Her sapma bir suçtur, ama her suç bir sapma sayılmaz', 'Sapma ile suç tamamen aynı kavramlardır', 'Suç yalnız resmi olmayan normlara aykırılıktır'], 'Suç yasalara aykırı davranıştır ve bu yüzden bir sapmadır; ancak görgü kurallarına aykırı olmak gibi birçok sapma suç sayılmaz.'),
  ('Merton\'un gerilim (anomi) kuramına göre toplumun kabul ettiği amaçları benimseyip bu amaçlara ulaşmak için yasal olmayan yollar kullanan bireyin uyum biçimi hangisidir?', 'Yenilikçilik', ['Ritüelcilik', 'Geri çekilme', 'Uyumculuk'], 'Merton\'a göre yenilikçi birey zenginlik gibi kültürel hedefleri kabul eder ama meşru araçlar yerine hırsızlık ya da dolandırıcılık gibi yollara başvurur.'),
  ('Hiçbir terfi beklentisi kalmamış bir memurun kurallara harfiyen uyup işini mekanik biçimde sürdürmesi Merton\'un hangi uyum biçimine örnektir?', 'Ritüelcilik', ['Yenilikçilik', 'Başkaldırı', 'Uyumculuk'], 'Ritüelcilikte birey kültürel hedeflerden vazgeçmiştir ama kurumsal araçlara ve kurallara sıkı sıkıya bağlı kalmaya devam eder.'),
  ('Howard Becker\'ın etiketleme kuramına göre bir davranışı sapma yapan temel etken hangisidir?', 'Toplumun ya da güçlü grupların o davranışı ve kişiyi "sapkın" olarak etiketlemesi', ['Davranışın biyolojik bir eğilimden kaynaklanması', 'Davranışın yalnızca yasada yazılı olması', 'Bireyin kişisel ahlaki kusurları'], 'Etiketleme kuramına göre sapma davranışın kendisinde değil, başkalarının ona yüklediği anlamdadır; etiketlenen birey zamanla bu kimliği benimseyebilir.'),
  ('Bir davranışın sapma sayılıp sayılmadığının toplumdan topluma ve dönemden döneme değişmesi neyi gösterir?', 'Sapmanın toplumsal olarak tanımlanan göreli bir kavram olduğunu', ['Sapmanın evrensel ve değişmez olduğunu', 'Sapmanın yalnızca biyolojik bir durum olduğunu', 'Sapmanın normlarla hiçbir ilişkisinin olmadığını'], 'Bir toplumda olağan sayılan davranış başka bir toplumda sapma sayılabilir; bu sapmanın göreli olduğunu gösterir.'),
  ('Kültürün ilk kapsamlı tanımlarından birini yaparak onu "bilgi, inanç, sanat, ahlak, hukuk, gelenek ve insanın toplum üyesi olarak edindiği diğer yetenek ve alışkanlıkların karmaşık bütünü" olarak tanımlayan antropolog kimdir?', 'Edward B. Tylor', ['Franz Boas', 'Clifford Geertz', 'Ruth Benedict'], 'Tylor bu tanımı 1871\'de yayımlanan İlkel Kültür adlı eserinde yapmıştır.'),
  ('Kültürün "birikimli" olması özelliği en iyi hangi örnekle açıklanır?', 'Her kuşağın önceki kuşaklardan aldığı bilgiye yenilerini eklemesi', ['Bir toplumun her yeni kuşakta kültürünü baştan ve sıfırdan yaratması', 'Kültürün bireyden bireye hiç değişmemesi', 'Kültürün yalnız tek kuşakta yaşaması'], 'Kültür, önceki kuşakların birikimine yeni bilgi ve deneyimlerin eklenmesiyle zenginleşir; yazı ve teknoloji bunun en açık örnekleridir.'),
  ('Bütün insan toplumlarında aile, din, dil ve süsleme gibi kültürel öğelerin bulunması hangi kavramla açıklanır?', 'Kültürel evrenseller', ['Kültürel görecelik ilkesi', 'Kültürel gecikme', 'Karşıt kültür'], 'George Murdock gibi antropologlar, her toplumda farklı biçimlerde de olsa bulunan ortak kültürel öğeleri kültürel evrenseller olarak adlandırmıştır.'),
  ('Belirli bir meslek grubunun, örneğin hekimlerin kendilerine özgü terimler kullanması ve ortak davranış biçimleri geliştirmesi hangi kavramla açıklanır?', 'Mesleki alt kültür', ['Karşıt kültür', 'Kültürel asimilasyon', 'Kültürel gecikme'], 'Meslek grupları kendi jargonları ve kurallarıyla, genel kültürün içinde bir alt kültür oluşturur.'),
  ('Karşıt kültürü alt kültürden ayıran temel özellik hangisidir?', 'Egemen kültürün temel değerlerine bilinçli olarak karşı çıkması', ['Genel kültürü olduğu gibi benimsemesi', 'Yalnızca küçük köylerde görülmesi', 'Yalnızca belirli bir meslek grubuna ait olması'], 'Karşıt kültür, toplumun ana değer ve normlarını reddeder ve onlara alternatif değerler önerir; alt kültür ise genel kültürle bir arada var olur.'),
  ('Bir ülkenin farklı bölgelerinde yöresel ağızların, yemeklerin ve halk danslarının farklılaşması kültür açısından nasıl değerlendirilir?', 'Ortak bir ulusal kültür içinde bölgesel alt kültürlerin bulunması', ['Ulusal kültürün hiç bulunmaması', 'Her bölgenin karşıt kültür oluşturması', 'Kültürün yalnız maddi öğelerden ibaret olması'], 'Bölgesel farklılıklar ortak kültürü reddetmez; onun içinde zenginlik yaratan alt kültürlerdir.'),
  ('Uzak bir ülkede icat edilen bir yemek tarifinin göç, ticaret ve iletişim yoluyla dünyanın pek çok yerinde yapılır hale gelmesi hangi kavramla açıklanır?', 'Kültürel yayılma', ['Kültürlenme', 'Kültürel gecikme', 'Karşıt kültür'], 'Kültürel yayılma, bir kültür öğesinin bir toplumdan diğerine geçmesidir.'),
  ('Maddi kültürün manevi kültürden daha hızlı değişmesiyle ortaya çıkan uyumsuzluğu "kültürel gecikme" olarak adlandıran sosyolog kimdir?', 'William F. Ogburn', ['Robert Park', 'Talcott Parsons', 'Pitirim A. Sorokin'], 'Ogburn 1922\'de yayımlanan Toplumsal Değişme adlı eserinde teknolojik değişmeye normların ve değerlerin geç uyum sağlamasını bu kavramla açıklamıştır.'),
  ('Kültürleşme ile asimilasyon arasındaki fark en iyi hangi seçenekte belirtilmiştir?', 'Kültürleşmede karşılıklı etkileşim olur, asimilasyonda bir kültür diğerinin içinde erir', ['Asimilasyonda kültürler hiç temas etmez', 'Kültürleşmede bir kültür tamamen yok olur', 'İkisi arasında hiçbir fark yoktur'], 'Kültürleşme kültürlerin birbirinden alışverişidir; asimilasyonda ise bir grup kendi kültürel kimliğini yitirerek baskın kültüre karışır.'),
  ('Etnosentrizm ile ilişkili olarak bir grubun üyelerine ait genellenmiş ve çoğu zaman yanlış yargılara ne ad verilir?', 'Kalıp yargı', ['Toplumsal değer', 'Kültürel evrensel ya da ortak öğe', 'Rol kümesi'], 'Kalıp yargılar, bir gruptaki herkese aynı özellikleri yükleyen basitleştirilmiş genellemelerdir; etnosentrik tutumları besler.'),
  ('Bir gencin giyim tarzını, müzik zevkini ve konuşma biçimini yaşıtlarına göre şekillendirmesi hangi toplumsallaşma ajansının etkisini gösterir?', 'Akran grubu', ['Devletin resmi kurumları ve yasalar', 'Ailenin büyükleri ve yaşlı akrabalar', 'Dinsel kurumlar ve ibadethaneler'], 'Akran grubu, özellikle ergenlik döneminde bireyin beğeni, tutum ve davranışlarını güçlü biçimde etkileyen bir toplumsallaşma ajansıdır.'),
  ('Okulun toplumsallaşmadaki rolünü aileden ayıran özellik hangisidir?', 'Çocuğa kişisel olmayan kurallar ve başarı ölçütleriyle değerlendirilmeyi öğretmesi', ['Çocuğa yalnızca duygusal bağlılık ve sevgi aşılaması, hiçbir kural getirmemesi', 'Çocuğun ilk dilini ve temel alışkanlıklarını kazandırması', 'Toplumsallaşmaya hiçbir katkıda bulunmaması'], 'Okulda çocuk herkese aynı biçimde uygulanan kurallarla ve kişisel başarıya göre değerlendirilmeyi öğrenir; bu ailedeki kişisel ilişkilerden farklıdır.'),
  ('Yıllarca bir köyde yaşamış emekli bir öğretmenin kente taşındıktan sonra bankacılık uygulamalarını, toplu taşıma kurallarını ve yeni komşuluk ilişkilerini öğrenmesi en iyi hangi kavramla açıklanır?', 'Yetişkin toplumsallaşması', ['Birincil toplumsallaşmanın başlangıcı', 'Kültürel evrenselin ortaya çıkması', 'Karşıt kültürün oluşumu'], 'Toplumsallaşma ömür boyu sürer; yetişkinler yeni ortam ve rollere uyum sağlarken de toplumsallaşmaya devam eder.'),
  ('Bireyin gelecekte üstleneceği bir statünün rollerini önceden öğrenmeye başlamasına ne ad verilir?', 'Beklenti toplumsallaşması', ['Yeniden toplumsallaşma süreci ve sonuçları', 'Geriye dönük kültürlenme', 'Ters toplumsallaşma ve etkileri'], 'Örneğin tıp öğrencisinin hekimlik rolünü staj sırasında öğrenmeye başlaması beklenti (öncül) toplumsallaşmadır.'),
  ('Askere alınan bir gencin sivil yaşam alışkanlıklarını bırakıp askeri disipline uygun yeni davranışlar edinmesi hangi kavramla açıklanır?', 'Yeniden toplumsallaşma', ['Birincil toplumsallaşmanın ilk aşaması', 'Kültürel yayılmanın yaygınlaşması', 'Toplumsal kategorinin oluşması'], 'Yeniden toplumsallaşma, bireyin eski değer ve davranışlarını bırakıp yenilerini edinmesidir; Goffman bunun yoğun yaşandığı yerleri "total kurumlar" olarak adlandırır.'),
  ('Goffman\'ın, üyelerin dış dünyadan yalıtılıp tek bir otorite altında sıkı biçimde düzenlenmiş bir yaşam sürdüğü yerleri adlandırmak için kullandığı kavram hangisidir?', 'Total kurum', ['İkincil grup ve gönüllü örgütler', 'Referans grubu ya da danışma grubu', 'Toplumsal kategori ya da istatistiksel grup'], 'Goffman Akıl Hastaneleri (Asylums) adlı eserinde hapishane, kışla ve yatılı kurumlar gibi yerleri total kurum olarak tanımlamıştır.'),
  ('Toplumdan yalıtılmış olarak büyümüş ve insanlarla uzun süre etkileşim kurmamış çocukların konuşma ve toplumsal davranışlarda ciddi güçlük çekmesi neyi gösterir?', 'Toplumsallaşmanın insan gelişimi için zorunlu olduğunu', ['Dilin tamamen kalıtımla edinildiğini ve öğrenmenin önemsiz olduğunu', 'Toplumsal davranışların doğuştan hazır geldiğini', 'Kültürün yalnızca okulda öğrenilebildiğini'], 'Yalıtılmış büyüyen çocuk örnekleri, insanın toplumsal yeteneklerinin ancak başkalarıyla etkileşim içinde gelişebildiğini gösterir.'),
  ('Televizyon ve sosyal medyanın günümüzde önemli bir toplumsallaşma ajansı sayılmasının nedeni hangisidir?', 'Geniş kitlelere değer, tutum ve yaşam modelleri sunması', ['Bireyle yüz yüze ve kişisel bağlar kurması, sevgi temelli ilişkiler sağlaması', 'Yalnızca bilimsel bilgi aktarması', 'Ailenin bütün işlevlerini tamamen ortadan kaldırması'], 'Kitle iletişim araçları bireylere davranış örnekleri, tüketim kalıpları ve değerler sunarak onların tutumlarını biçimlendirir.'),
  ('"Ayna benlik" kavramını ortaya atan sosyolog kimdir?', 'Charles H. Cooley', ['Erving Goffman', 'Herbert Blumer', 'George C. Homans'], 'Cooley\'e göre birey kendini başkalarının gözünden nasıl göründüğünü hayal ederek ve onların yargılarını yorumlayarak tanır.'),
  ('George Herbert Mead\'e göre benliğin iki yönünden toplumun beklentilerini ve kurallarını içselleştirmiş olan yönü hangisidir?', 'Toplumsal ben (me)', ['Kendiliğinden ben (I)', 'Ayna benliğin duygusal yönü', 'Kolektif bilinç'], 'Mead benliği "I" ve "me" olarak ayırır: "me" toplumun beklentilerini yansıtan toplumsal yön, "I" ise kendiliğinden ve yaratıcı tepki veren yöndür.'),
  ('Mead\'e göre bir çocuğun futbol oynarken yalnızca kendi rolünü değil, bütün takım arkadaşlarının ve rakiplerin rollerini hesaba katabilmesi hangi kavramın gelişimini gösterir?', 'Genelleştirilmiş öteki', ['Ayna benlik', 'Etiketleme', 'Rol çatışması'], 'Oyun aşamasında çocuk tek tek kişilerin değil, grubun bütününün beklentilerini (genelleştirilmiş öteki) dikkate almaya başlar.'),
  ('Mead\'e göre benliğin doğuştan var olmadığı, sonradan geliştiği görüşünün temel dayanağı hangisidir?', 'Benliğin toplumsal etkileşim ve dil aracılığıyla oluşması', ['Benliğin yalnızca genetik olarak belirlenmesi ve değişmemesi', 'Benliğin bireyin yalnız kalmasıyla kendiliğinden gelişmesi', 'Benliğin yalnızca okul eğitimiyle kazanılması'], 'Mead\'e göre benlik, sembollerle (özellikle dille) gerçekleşen etkileşim içinde ve başkalarının rollerini üstlenerek gelişir.'),
  ('Sınıf sistemini kast sisteminden ayıran temel özellik hangisidir?', 'Tabakalar arası geçişin görece açık olması', ['Konumun dinsel kurallarla doğuştan ve değişmez biçimde belirlenmesi', 'Evliliğin yalnızca aynı tabaka içinde zorunlu olması', 'Tabakaların hukuken ve kesin olarak tanımlanması'], 'Sınıf sisteminde konum büyük ölçüde ekonomik etkenlere bağlıdır ve eğitim, meslek gibi yollarla değişebilir.'),
  ('Davis-Moore kuramına çatışma yaklaşımından yöneltilen eleştiri hangisidir?', 'Ödüllerin işin önemini değil, gücü ve miras kalan avantajları yansıtabilmesi', ['Kuramın toplumsal eşitsizliği hiç tanımaması', 'Kuramın kast sistemini yücelterek tek örnek olarak alması', 'Kuramın yalnız küçük grupları incelemesi'], 'Eleştirmenler, birçok yüksek ücretli işin toplumsal önemiyle orantılı olmadığını ve fırsatların eşit dağılmadığını vurgular.'),
  ('Bourdieu\'nün "habitus" kavramı neyi ifade eder?', 'Toplumsal konumla edinilen kalıcı eğilimleri', ['Bireyin yasal haklarının toplamını ve korunmasını', 'Bir ülkenin ekonomik büyüme hızını', 'Kentlerin mekânsal planlamasını ve imar düzenini'], 'Habitus, bireyin içinde yetiştiği toplumsal konumla edindiği, düşünme, algılama ve davranma biçimlerini yönlendiren kalıcı eğilimler bütünüdür.'),
  ('Bir toplumdaki tabakalaşmanın göstergesi olarak en çok kullanılan ölçütler hangi seçenekte birlikte verilmiştir?', 'Gelir, meslek ve eğitim', ['Boy, kilo ve göz rengi', 'Doğum yeri, burç ve el yazısı', 'Hava durumu, mevsim ve iklim'], 'Tabakalaşma araştırmalarında gelir, servet, meslek ve eğitim düzeyi toplumsal konumu belirleyen temel ölçütlerdir.'),
  ('Bir tüccarın iflas ederek gündelik işçi olarak çalışmaya başlaması hakkında hangisi söylenebilir?', 'Aşağı doğru dikey hareketlilik yaşamıştır', ['Yatay hareketlilik yaşamıştır', 'Kuşaklar arası yukarı hareketlilik yaşamıştır', 'Statüsünde hiçbir değişme olmamıştır'], 'Toplumsal hiyerarşide daha alt bir konuma geçiş, aşağı doğru dikey hareketliliktir.'),
  ('Pitirim Sorokin\'in toplumsal hareketlilik kavramını sistemli biçimde ele aldığı eserinde dikey hareketliliğin "kanalları" olarak saydığı kurumlara örnek hangisidir?', 'Ordu, kilise, okul', ['Mahalle, sokak, park', 'Aile albümü, takvim, saat', 'Dağlar, ırmaklar, ovalar'], 'Sorokin 1927 tarihli Toplumsal Hareketlilik adlı eserinde ordu, kilise, okul, siyasal ve ekonomik örgütleri bireylerin yükselmesini sağlayan kanallar olarak ele almıştır.'),
  ('Uzun süren bir kuraklığın bir bölgedeki halkın tarımı bırakıp başka yerlere göç etmesine yol açması hangi değişme etkenine örnektir?', 'Doğal çevre etkeni', ['Teknolojik buluş ve yenilik', 'Kültürel yayılma ve ticaret', 'Siyasal devrim ve rejim değişikliği'], 'İklim, doğal afetler ve çevre koşulları toplumların yaşam biçimini değiştirebilen etkenlerdir.'),
  ('Toplumsal değişmenin hızı açısından geleneksel toplumlar ile modern toplumlar karşılaştırıldığında hangisi söylenebilir?', 'Modern toplumlarda değişme genellikle daha hızlıdır', ['Geleneksel toplumlarda değişme her zaman daha hızlı ve köklüdür', 'Her iki toplum türünde de hiçbir değişme yaşanmaz', 'Değişme hızı yalnızca nüfusun büyüklüğüne bağlıdır'], 'Teknoloji, iletişim ve kentleşme modern toplumlarda değişmeyi hızlandırır; geleneksel toplumlarda değişme daha yavaştır.'),
  ('Toplumsal değişmeyi açıklayan "evrimci" yaklaşımların ortak varsayımı hangisidir?', 'Toplumların basitten karmaşığa doğru aşamalarla geliştiği', ['Toplumların sürekli bir döngü içinde başa döndüğü', 'Toplumsal değişmenin yalnızca rastlantıyla ve hiçbir düzen olmadan gerçekleştiği', 'Toplumların hiçbir zaman değişmediği'], 'Comte ve Spencer gibi evrimci düşünürler toplumların belirli aşamalardan geçerek basitten karmaşığa doğru ilerlediğini savunur.'),
  ('Pitirim Sorokin\'in toplumsal değişme kuramında kültürlerin "ideasyonel" (manevi) ve "duyusal" (maddeci) evreler arasında gidip geldiği görüşü hangi tür değişme yaklaşımına girer?', 'Döngüsel yaklaşım', ['Doğrusal ilerlemeci yaklaşım', 'Çatışmacı yaklaşım', 'Yayılmacı (difüzyonist) yaklaşım'], 'Sorokin kültürlerin manevi değerlerin baskın olduğu evreler ile duyusal-maddi değerlerin baskın olduğu evreler arasında salındığını savunur; bu döngüsel bir yaklaşımdır.'),
  ('Bir toplumda yeni bir teknolojinin yaygınlaşmasına bazı grupların direnmesinin olası nedeni hangisidir?', 'Alışılmış yaşam biçimi ve çıkarların tehdit altında hissedilmesi', ['Yeni teknolojinin her zaman hiçbir yarar sağlamaması', 'Toplumsal değişmenin yasalarla yasaklanmış olması', 'Toplumların değişmeyi hiçbir koşulda kabul etmemesi'], 'Gelenekler, alışkanlıklar ve ekonomik çıkarlar yeniliklere direnç oluşturabilir; örneğin el dokumacılarının makinelere karşı çıkması.'),
  ('Bir ülkede kadınların eğitime ve çalışma yaşamına katılımının artmasının aile yapısını, evlilik yaşını ve çocuk sayısını değiştirmesi toplumsal değişmenin hangi özelliğini gösterir?', 'Bir alandaki değişmenin diğer alanları da etkilemesini', ['Değişmenin yalnızca tek bir kurumla sınırlı kalmasını', 'Değişmenin her zaman yukarıdan zorla yapılmasını', 'Değişmenin toplumsal yapıyı hiç etkilememesini'], 'Toplumsal kurumlar birbirine bağlı olduğundan eğitim ve ekonomideki bir değişme aile kurumunu da dönüştürür.'),
  ('Göçü açıklayan "itici-çekici etkenler" yaklaşımında hangisi kırsal bölgeden kişiyi iten bir etkendir?', 'Tarımda makineleşmeyle iş olanaklarının azalması', ['Kentte daha yüksek ücretli iş olanakları bulunması', 'Kentte eğitim ve sağlık hizmetlerinin daha iyi olması', 'Kentte eğlence ve kültür olanaklarının fazlalığı'], 'İtici etkenler kişiyi bulunduğu yerden ayrılmaya zorlayan koşullardır; çekici etkenler ise göç edilen yerin olanaklarıdır.'),
  ('Hızlı göç sonucu kentlerin çevresinde planlı olmayan, çoğunlukla izinsiz yapılan konut alanlarının oluşmasına Türkiye\'de verilen ad hangisidir?', 'Gecekondulaşma', ['Soylulaştırma', 'Banliyöleşme', 'Kentsel dönüşüm'], 'Gecekondu, 1950\'lerden sonra kırdan kente göçle birlikte kent çeperlerinde izinsiz ve plansız olarak yapılan konutlara verilen addır.'),
  ('Eski ve yoksul bir kent mahallesine orta ve üst gelirli grupların yerleşmesiyle konut fiyatlarının yükselmesi ve eski sakinlerin bölgeden çıkmak zorunda kalmasına ne ad verilir?', 'Soylulaştırma', ['Gecekondulaşma ve çarpık yapılaşma', 'Kırsallaşma', 'Banliyöleşme'], 'Soylulaştırma, bir bölgenin yenilenmesiyle sosyal yapısının değişmesi ve düşük gelirli sakinlerin yerinden edilmesidir.'),
  ('Kent yaşamının bireyler üzerinde yarattığı uyarı yoğunluğunu ve buna karşı geliştirilen "umursamaz (blasé) tutum"u inceleyen sosyolog kimdir?', 'Georg Simmel', ['Robert Merton', 'Auguste Comte', 'Emile Durkheim'], 'Simmel 1903 tarihli Metropol ve Zihinsel Yaşam adlı denemesinde büyük kentin bireyde ilgisizlik ve mesafeli bir tutum geliştirdiğini savunur.'),
  ('1920\'lerde kentsel yaşamı ve göçmen mahallelerini alan araştırmalarıyla inceleyen ve kent sosyolojisinin öncüsü sayılan okul hangisidir?', 'Chicago Okulu', ['Frankfurt Okulu', 'Annales Okulu', 'Viyana Çevresi'], 'Robert Park ve Ernest Burgess gibi sosyologlar Chicago kentini bir laboratuvar gibi inceleyerek kent sosyolojisinin temellerini atmıştır.'),
  ('Kırdan kente göç eden kişilerin kentte hemşehrilik ağları kurmasının temel işlevi hangisidir?', 'Kentte iş, konut ve dayanışma desteği sağlaması', ['Göçmenlerin kentle ve köyleriyle bütün bağlarını koparması', 'Kentteki bütün resmi kurumların yerine geçmesi', 'Kentlerdeki nüfusun azalmasına yol açması'], 'Hemşehrilik bağları göçmenlere iş bulma, konut edinme ve kentsel yaşama uyumda dayanışma sağlar.'),
  ('Kent yaşamının köy yaşamından ayrılan sosyolojik özelliklerinden biri hangisidir?', 'Uzmanlaşmanın ve ilişkilerde resmiliğin artması', ['Herkesin birbirini yakından tanıması ve yüz yüze ilişkilerin egemen olması', 'Ekonominin büyük ölçüde tarıma dayanması', 'Geleneklerin bütün davranışları belirlemesi'], 'Kentlerde işbölümü ve uzmanlaşma artar; ilişkiler çoğu zaman amaca yönelik ve kişisel olmayan bir nitelik kazanır.'),
  ('İletişim teknolojileri sayesinde dünyanın küçük bir köye dönüştüğünü anlatan "küresel köy" kavramını ortaya atan düşünür kimdir?', 'Marshall McLuhan', ['Anthony Giddens', 'Immanuel Wallerstein', 'Zygmunt Bauman'], 'Kanadalı iletişim kuramcısı McLuhan, elektronik medyanın uzaklıkları ortadan kaldırarak dünyayı bir köy gibi birbirine bağladığını savunmuştur.'),
  ('Küresel ürün ve fikirlerin yerel kültürlere uyarlanarak benimsenmesini anlatan kavram hangisidir?', 'Glokalleşme (küyerelleşme)', ['Asimilasyon', 'Kültürel gecikme (Ogburn)', 'Etnosentrizm'], 'Glokalleşme, küresel öğelerin yerel koşullara göre biçimlenmesidir; örneğin uluslararası bir zincirin menüsüne yöresel yemekler eklemesi.'),
  ('Dünyayı merkez, yarı çevre ve çevre ülkeler olarak ayıran "dünya sistemleri" kuramını geliştiren sosyolog kimdir?', 'Immanuel Wallerstein', ['Talcott Parsons ve öğrencileri', 'Daniel Bell', 'Ulrich Beck'], 'Wallerstein, kapitalist dünya ekonomisinde ülkelerin işbölümüne göre merkez, yarı çevre ve çevre konumlarında yer aldığını savunmuştur.'),
  ('George Ritzer\'in "McDonaldlaşma" kavramı, Weber\'in hangi düşüncesinin günümüze uyarlanmasıdır?', 'Rasyonelleşme', ['Karizmatik otorite', 'Değer-rasyonel eylem', 'Protestan ahlakı'], 'Ritzer, hızlı yemek zincirlerinin verimlilik, hesaplanabilirlik, öngörülebilirlik ve denetim ilkelerinin toplumun pek çok alanına yayılmasını Weber\'in rasyonelleşme kavramıyla açıklar.'),
  ('Modern toplumların ürettiği küresel ölçekli tehlikeleri, örneğin çevre felaketlerini merkeze alan "risk toplumu" kavramını geliştiren sosyolog kimdir?', 'Ulrich Beck', ['Jürgen Habermas', 'Pierre Bourdieu', 'Max Weber'], 'Alman sosyolog Ulrich Beck, 1986\'da yayımlanan Risk Toplumu adlı eserinde modernleşmenin kendi yarattığı riskleri yönetmek zorunda kaldığını savunmuştur.'),
  ('Küreselleşmeye yöneltilen eleştirilerden biri hangisidir?', 'Kültürlerin tek tipleşmesine ve yerel kültürlerin zayıflamasına yol açabilmesi', ['Ülkeler arasındaki iletişimi tamamen kesmesi', 'Uluslararası ticareti ortadan kaldırması', 'Teknolojinin yayılmasını durdurması'], 'Eleştirmenler, küreselleşmenin güçlü ülkelerin kültürünü yayarak yerel kültürleri baskı altına alabileceğini ileri sürer.'),
  ('Zygmunt Bauman\'ın günümüz toplumunu nitelemek için kullandığı "akışkan modernlik" kavramı neyi vurgular?', 'İlişkilerin, kimliklerin ve kurumların kalıcılığını yitirip sürekli değişmesini', ['Toplumların geleneksel yapıya geri dönmesini', 'Kurumların hiç değişmeden kuşaklar boyu sürmesini', 'Sanayi üretiminin tek ekonomik etkinlik olmasını'], 'Bauman\'a göre günümüzde bağlar, işler ve kimlikler katı biçimlerini yitirerek sıvı gibi akışkan ve geçici hale gelmiştir.'),
  ('Toplumsal kurumların temel özelliklerinden biri hangisidir?', 'Birbirleriyle bağlantılı olmaları ve birindeki değişmenin diğerlerini etkilemesi', ['Birbirinden tamamen bağımsız işlemeleri ve hiç etkileşmemeleri', 'Kısa sürede ortaya çıkıp hızla yok olmaları', 'Yalnızca tek bir bireyin iradesiyle kurulmaları'], 'Kurumlar bir sistem oluşturur; örneğin ekonomideki değişmeler aileyi, eğitimi ve siyaseti de etkiler.'),
  ('Bir toplumda nüfusun beslenme, barınma ve giyinme ihtiyaçlarını karşılamaya yönelik üretim, dağıtım ve tüketim düzenlemeleri hangi kurumun alanına girer?', 'Ekonomi', ['Din', 'Eğitim', 'Aile ve akrabalık'], 'Ekonomi kurumu mal ve hizmetlerin üretimi, dağıtımı ve tüketimiyle ilgili düzenlemeleri kapsar.'),
  ('Tarım toplumlarında geniş ailenin yaygın olmasının temel nedeni hangisidir?', 'Toprağı işlemek için çok sayıda insan gücüne ihtiyaç duyulması', ['Kentlerde konutların çok geniş ve ucuz olması', 'Bireyciliğin ve kişisel bağımsızlığın en yüksek değer olması', 'Ücretli emeğin ve fabrika üretiminin yaygın olması'], 'Tarımsal üretim ailenin ortak emeğine dayanır; bu yüzden geniş aile bir üretim birimi olarak işlev görür.'),
  ('Sanayileşmeyle birlikte çekirdek ailenin yaygınlaşmasının sosyolojik açıklaması hangisidir?', 'Ücretli emek ve coğrafi hareketliliğin küçük aileyi elverişli kılması', ['Akrabalık bağlarının yasalarla yasaklanması ve cezalandırılması', 'Kentlerde evlilik kurumunun tamamen ortadan kalkması', 'Tarım üretiminin kentlerde artması'], 'Sanayi toplumunda birey işini kendi kazanır ve iş için yer değiştirebilir; küçük aile bu hareketliliğe daha uygun düşer.'),
  ('Talcott Parsons\'a göre modern çekirdek ailenin kalan en temel iki işlevi hangileridir?', 'Çocuğun birincil toplumsallaşması ve yetişkinlerin kişilik dengesinin sağlanması', ['Ekonomik üretim ve siyasal yönetim', 'Dinsel törenlerin yönetimi ve askeri koruma', 'Eğitim ve sağlık hizmetlerinin tamamen sağlanması'], 'Parsons, modern ailenin çocukların toplumsallaşması ile yetişkinlerin duygusal dengesini sağlama işlevlerinde uzmanlaştığını savunur.'),
  ('Bir ailede evin gelirini sağlayan babanın aynı zamanda aile içindeki bütün önemli kararları tek başına alması aile yapısı açısından neyi gösterir?', 'Ataerkil otorite yapısını', ['Anaerkil otorite yapısını', 'Eşitlikçi otorite yapısını', 'Anaerkil yerleşim kuralını'], 'Otoritenin baba ya da en yaşlı erkekte toplandığı aile yapısı ataerkil olarak nitelendirilir.'),
  ('Bir toplulukta evliliklerin yalnızca aynı aşiret, kast ya da köy içinden yapılmasının istenmesi hangi evlilik kuralını yansıtır?', 'Endogami (iç evlilik)', ['Egzogami (dış evlilik)', 'Poliandri', 'Poligini'], 'Endogami, bireyin kendi grubunun içinden eş seçmesini öngören kuraldır.'),
  ('Bir toplulukta aynı soydan ya da aynı klandan biriyle evlenmenin yasak olması ve eşin başka bir gruptan seçilmesi hangi kuraldır?', 'Egzogami (dış evlilik)', ['Endogami (iç evlilik kuralı)', 'Monogami', 'Poliandri'], 'Egzogami, eşin kendi grubunun dışından seçilmesini zorunlu kılan kuraldır.'),
  ('Endogami ve egzogami kurallarının aynı toplumda birlikte bulunabilmesi nasıl açıklanır?', 'Kuralların farklı grup düzeylerine uygulanabilmesiyle', ['Bu iki kuralın aslında aynı anlama gelmesiyle', 'Toplumun evlilik kuralı bulunmamasıyla', 'Her iki kuralın da yalnızca poligamiyle ilgili olmasıyla'], 'Örneğin bir toplumda eşin aynı köyden (endogami) ama farklı bir sülaleden (egzogami) seçilmesi istenebilir; kurallar farklı grup düzeylerini hedefler.'),
  ('Kocası ölen kadının, kocasının erkek kardeşiyle evlenmesini öngören gelenek hangi adla bilinir?', 'Levirat', ['Sororat', 'Poliandri', 'Egzogami'], 'Levirat geleneğinde dul kadın kocasının kardeşiyle evlenir; Türk toplumunda bu uygulama "yengeyle evlenme" olarak da bilinir.'),
  ('Karısı ölen erkeğin, karısının kız kardeşiyle evlenmesini öngören geleneğe ne ad verilir?', 'Sororat', ['Levirat', 'Poligini', 'Endogami'], 'Sororat geleneğinde dul erkek ölen eşinin kız kardeşiyle evlenir; böylece iki aile arasındaki bağ sürdürülür.'),
  ('Levirat ve sororat geleneklerinin geleneksel toplumlardaki temel işlevi hangisidir?', 'Aileler arası bağları ve mülkün aile içinde kalmasını sağlamak', ['Bireyin eşini tamamen özgürce seçmesini sağlamak', 'Evliliğin hiçbir kurala bağlı olmamasını sağlamak', 'Kentleşmeyi hızlandırmak ve köyleri boşaltmak amacıyla uygulanmak'], 'Bu gelenekler evlilikle kurulan aileler arası ittifakın, mülkün ve çocukların bakımının aile içinde sürmesini sağlar.'),
  ('Eğitimin "bireyleri meslek yaşamına hazırlama" işlevi hangi kurumla doğrudan bağlantılıdır?', 'Ekonomi kurumu', ['Din kurumu', 'Aile kurumu', 'Akrabalık kurumu'], 'Eğitim, ekonomi kurumunun ihtiyaç duyduğu nitelikli iş gücünü yetiştirir; bu iki kurum arasında güçlü bir bağ vardır.'),
  ('Okullarda resmi müfredatta yer almadığı halde öğrencilere dakiklik, otoriteye uyum ve sırayla konuşma gibi değer ve davranışların öğretilmesine ne ad verilir?', 'Örtük program', ['Resmi müfredat', 'Ders dışı etkinlik', 'Mesleki eğitim'], 'Örtük program, açıkça yazılmamış ama okul yaşamı içinde öğrencilerin edindiği değer, tutum ve davranışlardır.'),
  ('Okulda farklı bölgelerden gelen öğrencilerin ortak dil, ortak tarih bilinci ve ortak değerler edinmesi eğitimin hangi işlevine örnektir?', 'Toplumsal bütünleştirme işlevi', ['Ekonomik üretim işlevi', 'Biyolojik işlev ve neslin devamı', 'Dinsel tören düzenleme işlevi'], 'Eğitim, farklı kesimlerden gelen bireylere ortak bir kültür kazandırarak toplumsal bütünleşmeye katkıda bulunur.'),
  ('Eğitimin toplumsal hareketlilikteki rolü en iyi hangi ifadeyle değerlendirilir?', 'Yükselmeye olanak sağlar, ama fırsat eşitsizlikleri bu etkiyi sınırlayabilir', ['Eğitim her koşulda herkesi eşit biçimde en üst tabakaya taşır', 'Eğitimin toplumsal konum üzerinde hiçbir etkisi yoktur', 'Eğitim yalnızca aşağı doğru hareketliliğe yol açar'], 'Eğitim önemli bir hareketlilik kanalıdır; ancak ailenin gelir ve kültürel birikimi gibi etkenler eğitime erişimi ve başarıyı etkiler.'),
  ('Bir okulun öğrencileri ilk sınıflardan itibaren başarı düzeylerine göre farklı şubelere ayırması ve bunun öğrencilerin gelecek beklentilerini etkilemesi sosyolojide hangi kavramla incelenir?', 'İzleme (tracking) ya da yetenek gruplaması', ['Kültürel yayılma ve kültürleşme', 'Toplumsal kategori ve sınıflama', 'Mekanik dayanışma ve benzerlik'], 'İzleme ya da yetenek gruplaması, öğrencileri erken yaşta farklı şubelere ayırarak onlara farklı beklenti ve olanaklar sunar; bu da var olan eşitsizlikleri pekiştirebilir.'),
  ('Modernleşmeyle birlikte dinsel kurumların siyaset, eğitim ve hukuk gibi alanlar üzerindeki etkisinin azalmasını anlatan sosyolojik kavram hangisidir?', 'Sekülerleşme', ['Kültürleşme', 'Kurumsallaşma', 'Kentleşme'], 'Sekülerleşme, dinin toplumsal kurumlar ve kamusal yaşam üzerindeki belirleyiciliğinin azalması sürecidir.'),
  ('Sosyolojide "dinsel kurum" ile "dinsel inanç" arasında yapılan ayrımın gerekçesi hangisidir?', 'Kurumun inancın örgütlü, kurallı ve toplumsal biçimini anlatması', ['Dinsel inancın yalnızca yazılı kurallardan oluşması', 'Dinsel kurumun yalnızca bireyin iç dünyasıyla ilgili olması', 'İkisinin her zaman tamamen aynı şey olması'], 'İnanç bireysel ve öznel olabilir; kurum ise bu inancın ritüeller, roller, kurallar ve örgütlerle toplumsal olarak düzenlenmiş biçimidir.'),
  ('Bir köyde cami derneğinin kurulması, imamın lojmanının köylülerce birlikte yapılması ve ramazanda iftar sofrası kurulması, sosyolojik açıdan dinin hangi boyutunu gösterir?', 'Topluluk ve dayanışma boyutunu', ['Yalnızca bireysel inanç boyutunu', 'Ekonomik üretim boyutunu', 'Siyasal iktidar boyutunu'], 'Bu örneklerde din, insanları ortak etkinliklerde bir araya getiren ve dayanışma üreten bir toplumsal kurum olarak işlev görür.'),
  ('Bir toplu iğne imalathanesi örneğiyle işbölümünün verimliliği büyük ölçüde artırdığını gösteren düşünür kimdir?', 'Adam Smith', ['Karl Marx', 'Emile Durkheim', 'Max Weber'], 'Adam Smith 1776\'da yayımlanan Ulusların Zenginliği adlı eserinde, iğne üretiminin aşamalara bölünmesiyle verimin çok arttığını anlatmıştır.'),
  ('Avcı-toplayıcı toplumlarda işbölümünün temel ölçütü genellikle hangileridir?', 'Yaş ve cinsiyet', ['Diploma ve meslek sertifikası', 'Sermaye ve hisse senedi sahipliği', 'Kast ve hukuki zümre üyeliği'], 'Basit toplumlarda işler çoğunlukla yaş ve cinsiyete göre paylaşılır; uzmanlaşma sınırlıdır.'),
  ('Sanayi toplumunda aşırı uzmanlaşmanın işçi açısından olası olumsuz sonuçlarından biri hangisidir?', 'İşin tekdüzeleşmesi ve işçinin ürünün bütününden kopması', ['İşçinin bütün üretim aşamalarını tek başına yönetmesi', 'Üretim veriminin tamamen ve kalıcı olarak düşmesi, fabrikaların kapanması', 'İşbölümünün tamamen ortadan kalkması'], 'Bir işçinin yalnızca küçük bir işlemi yapması tekdüzelik ve yabancılaşmaya yol açabilir; Marx bu durumu eleştirmiştir.'),
  ('Orta Çağ Avrupası\'nda toprağın soylulara ait olduğu ve köylülerin toprağa bağlı olarak ürünün bir kısmını beye verdiği ekonomik düzen hangisidir?', 'Feodalizm', ['Kapitalizm', 'Sosyalizm', 'Sanayi toplumu'], 'Feodalizmde toprak beyin mülkiyetindedir; serfler toprağa bağlıdır ve emeklerinin ya da ürünlerinin bir kısmını bey\'e verirler.'),
  ('Bir toplumda çalışanların yaklaşık yüzde 70\'inin tarımda, yüzde 10\'unun sanayide, yüzde 20\'sinin hizmetlerde çalıştığı biliniyor. Bu toplum hakkında en uygun çıkarım hangisidir?', 'Tarım toplumu özellikleri ağır basmaktadır', ['Sanayi sonrası toplum aşamasındadır', 'Avcı-toplayıcı bir toplumdur', 'Hizmet sektörüne dayalı bir bilgi toplumudur'], 'Çalışanların büyük çoğunluğunun tarımda olması, ekonominin tarıma dayandığını gösterir.'),
  ('Weber\'in sosyolojisinde "otorite"yi çıplak güçten ayıran özellik hangisidir?', 'Yönetilenlerce meşru kabul edilmesi', ['Yalnızca silah zoruyla uygulanması', 'Hiçbir kurala dayanmaması', 'Yalnızca ekonomik alanda geçerli olması'], 'Otorite, meşru sayılan ve bu nedenle gönüllü olarak itaat edilen güçtür.'),
  ('Weber\'in meşru otorite türleri hangi seçenekte doğru olarak verilmiştir?', 'Geleneksel, karizmatik, yasal-ussal', ['Mekanik, organik ve karma dayanışma', 'Teolojik, metafizik, pozitif', 'Birincil, ikincil, referans'], 'Weber otoriteyi meşruiyet kaynağına göre geleneksel, karizmatik ve yasal-ussal (rasyonel-yasal) olarak üçe ayırır.'),
  ('Bir aşiret reisinin yetkisini atalarından devraldığı ve bu yetkinin süregelen göreneklerle meşru sayıldığı otorite türü hangisidir?', 'Geleneksel otorite', ['Karizmatik otorite', 'Yasal-ussal otorite', 'Bürokratik otorite'], 'Geleneksel otoritenin meşruiyeti, kuşaklardır sürdürülen geleneklere ve kutsal sayılan alışkanlıklara dayanır.'),
  ('Olağanüstü kişisel nitelikleri ve etkileyiciliği nedeniyle izleyicilerinin kendisine bağlandığı bir liderin otoritesi Weber\'e göre hangi türdendir?', 'Karizmatik otorite', ['Geleneksel otorite', 'Yasal-ussal otorite', 'Ataerkil otorite'], 'Karizmatik otorite, liderin olağanüstü sayılan kişisel niteliklerine duyulan inanç ve bağlılığa dayanır.'),
  ('Bir valinin yetkisini kişisel özelliklerinden ya da soyundan değil, yasalarla tanımlanmış görevinden alması hangi otorite türüne örnektir?', 'Yasal-ussal otorite', ['Karizmatik otorite', 'Geleneksel otorite', 'Ataerkil (patriarkal) otorite'], 'Yasal-ussal otoritede itaat kişiye değil, yasalarla belirlenmiş makama ve kurallara yöneliktir; modern devlet ve bürokrasinin temelidir.'),
  ('Robert Michels\'in "oligarşinin tunç yasası" olarak adlandırdığı görüş neyi öne sürer?', 'Büyük örgütlerin zamanla küçük bir yönetici azınlığın denetimine girdiğini', ['Her örgütün zamanla tamamen eşitlikçi hale geldiğini', 'Örgütlerin büyüdükçe dağıldığını', 'Siyasal partilerin hiçbir zaman lider çıkarmadığını'], 'Michels, demokratik amaçlarla kurulan parti ve sendikalarda bile yönetimin zamanla küçük bir seçkin grupta toplandığını savunmuştur.'),
  ('Bürokraside memurların kişisel duygularını işe katmadan herkese aynı kuralları uygulaması ilkesi hangisidir?', 'Kişisellikten uzaklık', ['Karizmatik yönetim', 'Geleneksel bağlılık ve sadakat ilkesi', 'Kayırmacılık'], 'Gayrişahsilik, işlemlerin kişiye göre değil kurallara göre yapılmasıdır; eşit muameleyi amaçlar.'),
  ('Merton\'un bürokrasi eleştirisinde kurallara uymanın bir amaç olmaktan çıkıp kendi başına amaç haline gelmesine ne ad verilir?', 'Amaç değişimi', ['Karizmanın rutinleşmesi', 'Yapısal hareketlilik', 'Dünyanın büyüsünün bozulması süreci'], 'Merton\'a göre memur kurallara aşırı bağlanınca asıl amacı unutabilir; kurallar araç olmaktan çıkıp amaç haline gelir.'),
  ('Bir vatandaşın basit bir işlem için farklı birimlerden çok sayıda imza toplamak zorunda kalması ve işin haftalarca sürmesi günlük dilde hangi kavramla eleştirilir?', 'Kırtasiyecilik', ['Liyakat', 'Gayrişahsilik ilkesi', 'Uzmanlaşma'], 'Kırtasiyecilik, bürokrasinin aşırı kural ve işlem yükü yüzünden hantallaşmasını anlatan yaygın bir eleştiridir.'),
  ('Medyanın insanlara neyi düşüneceklerini değil, ne hakkında düşüneceklerini, yani hangi konuları önemli sayacaklarını belirlemede etkili olduğunu savunan yaklaşım hangisidir?', 'Gündem belirleme kuramı', ['Kültürel gecikme kuramı', 'Etiketleme kuramı', 'Asabiyet kuramı'], 'McCombs ve Shaw\'un geliştirdiği gündem belirleme kuramına göre medyanın bir konuya verdiği önem, kamuoyunun o konuyu önemli bulmasını etkiler.'),
  ('Kültürün sanayi ürünleri gibi standart biçimde üretilip pazarlanmasını eleştiren "kültür endüstrisi" kavramı hangi düşünce okuluna aittir?', 'Frankfurt Okulu', ['Chicago Okulu', 'Annales Okulu', 'Le Play Okulu'], 'Adorno ve Horkheimer, Aydınlanmanın Diyalektiği adlı eserlerinde kitle kültürünün eleştirel düşünceyi körelttiğini savunarak kültür endüstrisi kavramını geliştirmiştir.'),
  ('Sosyal medyanın toplumsal etkileşim üzerindeki etkilerinden biri hangisidir?', 'Coğrafi uzaklıklara rağmen ilişki ağlarının sürdürülebilmesi', ['Yüz yüze ilişkilerin tamamen ve kesin olarak sona ermesi', 'İletişimin yalnızca resmi kurumlarla sınırlanması', 'Bilginin yayılma hızının büyük ölçüde azalması'], 'Sosyal medya, farklı yerlerdeki insanların sürekli iletişimde kalmasını kolaylaştırarak ilişki ağlarını genişletir.'),
  ('Bir köye ilk kez televizyon gelmesinden sonra gençlerin giyim ve konuşma tarzlarının kentlilere benzemeye başlaması hangi kurumun toplumsallaştırıcı etkisine örnektir?', 'Kitle iletişim araçlarının', ['Akrabalık sisteminin', 'Dinî kurumların', 'Köy ihtiyar heyetinin'], 'Televizyon yeni yaşam modelleri sunarak özellikle gençlerin tutum ve davranışlarını etkiler.'),
  ('Merton\'un bilim insanlarının uyması beklenen normlar arasında saydığı "evrenselcilik" ilkesi neyi ifade eder?', 'Bilimsel iddiaların, sahibinin kimliğine bakılmadan nesnel ölçütlerle değerlendirilmesini', ['Bilimin yalnızca belirli ülkelerde yapılabilmesini', 'Bilim insanlarının bulgularını gizli tutmasını', 'Bilimsel bilginin değişmez olmasını'], 'Merton\'a göre bir iddia, ileri sürenin ırkı, ulusu ya da dininden bağımsız olarak kanıt ve mantık ölçütleriyle değerlendirilmelidir.'),
  ('Bir yılda 1.000 kişilik nüfusta 18 doğum ve 6 ölüm gerçekleşirse, göç olmadığı varsayıldığında doğal nüfus artış hızı binde kaçtır?', '12', ['24', '18', '6'], 'Doğal artış hızı doğum hızı ile ölüm hızı arasındaki farktır: 18 - 6 = binde 12.'),
  ('Nüfusun geometrik, besin kaynaklarının ise aritmetik olarak arttığını öne sürerek kıtlık uyarısında bulunan düşünür kimdir?', 'Thomas Malthus', ['Adam Smith', 'David Ricardo', 'John Stuart Mill'], 'Malthus 1798\'de yayımlanan Nüfus İlkesi Üzerine Deneme adlı eserinde nüfus artışının besin üretimini aşacağını savunmuştur.'),
  ('Bir ülkede 0-14 yaş grubunun nüfusun yarısına yakın olduğu biliniyorsa, bu ülkenin en çok hangi alanda yatırım ihtiyacı olacağı söylenebilir?', 'Okul ve eğitim hizmetleri', ['Huzurevleri ve yaşlı bakımı', 'Emeklilik fonları', 'Bakımevi personeli'], 'Genç nüfusun yüksek olması, eğitim olanaklarına ve gelecekte istihdama olan ihtiyacın büyük olacağını gösterir.'),
  ('Bebek ölüm hızının yüksek olduğu toplumlarda ailelerin çok çocuk sahibi olmayı tercih etmesinin sosyolojik açıklaması hangisidir?', 'Çocuk kaybı riskine karşı neslin ve işgücünün güvenceye alınması', ['Çocukların hiçbir ekonomik katkısının olmaması', 'Kentlerde konutların çok ucuz olması', 'Eğitim masraflarının çok yüksek olması'], 'Geleneksel toplumlarda çocuklar hem tarımsal işgücü hem de yaşlılıkta güvencedir; yüksek bebek ölümü çok çocuk sahibi olmayı teşvik eder.'),
  ('Ekonomik krizle birlikte bir ülkede birçok fabrikanın kapanması sonucu ortaya çıkan işsizlik, sosyolojik açıdan nasıl değerlendirilir?', 'Yapısal etkenlerden doğan bir toplumsal sorun', ['Tamamen bireylerin tembelliğinden kaynaklanan bir durum', 'Yalnızca kültürel bir alışkanlık', 'Kişisel bir rol çatışması'], 'Çok sayıda kişiyi aynı anda etkileyen ve ekonomik yapıdan kaynaklanan işsizlik bireysel değil toplumsal bir sorundur.'),
  ('Yoksulluğun kuşaklar boyunca aynı ailelerde sürmesini açıklamaya çalışan "yoksulluk kültürü" kavramını ortaya atan antropolog kimdir?', 'Oscar Lewis', ['Margaret Mead', 'Bronislaw Malinowski', 'Claude Lévi-Strauss'], 'Oscar Lewis, yoksul topluluklarda gelişen bazı tutum ve davranışların yoksulluğun kuşaklar arası aktarımında rol oynadığını savunmuştur; kavram tartışmalı olup eleştirilere de konu olmuştur.'),
  ('Sosyoloji ile psikoloji arasındaki temel fark en iyi hangi seçenekte ifade edilmiştir?', 'Sosyolojinin toplumsal yapı ve ilişkileri, psikolojinin bireyin zihinsel süreçlerini incelemesi', ['Sosyolojinin yalnızca geçmişi, psikolojinin yalnızca geleceği incelemesi', 'Psikolojinin bilimsel yöntem kullanması, sosyolojinin kullanmaması', 'Sosyolojinin yalnız köyleri, psikolojinin yalnız kentleri incelemesi'], 'Sosyoloji bireyler arası ilişkileri ve kurumları; psikoloji bireyin davranışı ve zihinsel süreçlerini merkeze alır.'),
  ('Sosyolojinin tarihten yararlanmasına en uygun örnek hangisidir?', 'Osmanlı toprak düzeninin köy yapısına etkisinin arşivlerle incelenmesi', ['Bir ilacın etkisinin laboratuvarda deneyle ölçülmesi', 'Bir bireyin çocukluk anılarının terapide incelenmesi', 'Bir yıldızın uzaklığının teleskopla hesaplanması'], 'Tarihsel belgeler, bugünkü toplumsal yapıların kökenini anlamak için sosyolog açısından önemli bir veri kaynağıdır.'),
  ('Bir toplumun gelir düzeyi ve üretim yapısı ile aile büyüklüğü arasındaki ilişkiyi araştıran bir sosyolog en çok hangi bilim dalıyla işbirliği yapar?', 'Ekonomi', ['Dil bilimi', 'Arkeoloji', 'Jeoloji'], 'Gelir ve üretim yapısına ilişkin veriler ekonominin alanına girer; bunların aile yapısıyla ilişkilendirilmesi sosyoloji ile ekonominin ortak çalışma alanıdır.'),
  ('Yerleşme biçimlerini inceleyen bir sosyolog için coğrafya bilgisinin katkısını en iyi örnekleyen durum hangisidir?', 'Bir bölgenin yeryüzü şekillerinin yerleşme biçimini nasıl etkilediğinin incelenmesi', ['Bir dilin dil bilgisi kurallarının çıkarılması', 'Bir ülkenin anayasasının maddelerinin sayılması', 'Bir hastalığın tedavi yönteminin geliştirilmesi'], 'Coğrafi koşullar yerleşme, ekonomik etkinlik ve nüfus dağılımını etkilediğinden sosyolog bu bilgiden yararlanır.'),
  ('Toplumları askeri ve sanayi toplumları olarak ayıran ve "en uygun olanın hayatta kalması" ifadesini kullanan İngiliz düşünür kimdir?', 'Herbert Spencer', ['John Locke', 'Thomas Hobbes', 'Jeremy Bentham'], 'Spencer toplumların evrimini biyolojik evrime benzetmiş, askeri toplumlardan sanayi toplumlarına doğru bir gelişme öngörmüştür.'),
  ('Talcott Parsons\'ın AGIL şemasına göre her toplumsal sistemin karşılaması gereken dört işlevsel gereklilik hangileridir?', 'Uyum, amaca ulaşma, bütünleşme, örüntünün sürdürülmesi', ['Üretim, dağıtım, tüketim, tasarruf', 'Doğum, evlilik, göç, ölüm', 'Teolojik, metafizik, pozitif, endüstriyel'], 'Parsons\'a göre her sistem çevresine uyum (A), amaçlarını gerçekleştirme (G), parçalarını bütünleştirme (I) ve değer örüntülerini sürdürme (L) gereksinimlerini karşılamalıdır.'),
  ('Kamusal alan ve iletişimsel eylem kavramlarıyla tanınan, Frankfurt Okulu\'nun ikinci kuşağından Alman düşünür kimdir?', 'Jürgen Habermas', ['Theodor Adorno', 'Georg Simmel', 'Karl Mannheim'], 'Habermas, kamusal alanın yapısal dönüşümünü ve özgür, eşit tartışmaya dayalı iletişimsel eylemi incelemiştir.'),
  ('Anthony Giddens\'ın yapılaşma (strüktürasyon) kuramının temel düşüncesi hangisidir?', 'Yapının hem eylemi sınırladığı hem de eylemle sürekli yeniden üretildiği', ['Toplumsal yapının bireylerden tamamen bağımsız olduğu', 'Bireylerin yapıdan hiç etkilenmeden davrandığı', 'Toplumun yalnızca ekonomik yapıyla açıklanabileceği'], 'Giddens, yapı ile eylemi karşıt değil, birbirini karşılıklı olarak oluşturan öğeler olarak görür; buna yapının ikiliği der.'),
  ('Fransız sosyolog Gabriel Tarde toplumsal yaşamı açıklarken en çok hangi süreci öne çıkarmıştır?', 'Taklit', ['Anomi', 'Sınıf çatışması', 'Asabiyet'], 'Tarde, Taklit Yasaları adlı eserinde yeniliklerin toplumda bireyler arası taklit yoluyla yayıldığını savunmuştur.'),
  ('Karl Mannheim\'ın bilgi sosyolojisinin temel savı hangisidir?', 'Düşünce ve bilginin toplumsal konum ve koşullarla bağlantılı olduğu', ['Bilginin tamamen toplumdan bağımsız biçimde ortaya çıktığı', 'Bilginin yalnızca kalıtımla aktarıldığı', 'Bütün bilgilerin değişmez ve evrensel olduğu'], 'Mannheim, İdeoloji ve Ütopya adlı eserinde düşüncelerin, onları savunan grupların toplumsal konumuyla ilişkili olduğunu savunmuştur.'),
  ('Harold Garfinkel\'in geliştirdiği etnometodoloji yaklaşımı neyi inceler?', 'İnsanların gündelik yaşamı anlamlı kılmak için kullandığı örtük yöntemleri', ['Ülkelerin ekonomik büyüme oranlarını', 'Toplumların tarihsel evrim aşamalarını', 'Devletlerin askeri güç dengelerini'], 'Etnometodoloji, sıradan insanların günlük etkileşimlerde düzeni nasıl kurduklarını ve sürdürdüklerini inceler.'),
  ('Ahilik teşkilatının toplumsal yaşamdaki temel işlevi hangisidir?', 'Mesleki eğitim ile ahlaki değerleri birleştirerek esnaf arasında dayanışma sağlamak', ['Devlet adına askeri vergi toplamak', 'Yalnızca dinsel törenleri yönetmek', 'Köylülerin toprak mülkiyetini düzenlemek'], '13. yüzyılda Anadolu\'da Ahi Evran\'la özdeşleşen ahilik, zanaat eğitimiyle birlikte dürüstlük ve yardımlaşma değerlerini öğreten bir esnaf örgütüydü.'),
  ('Geleneksel Türk toplumunda "komşuluk" ilişkilerinin güçlü olması en çok hangi dayanışma türüyle ilişkilendirilebilir?', 'Mekanik dayanışma', ['Organik dayanışma', 'Bürokratik dayanışma', 'Sözleşmeye dayalı dayanışma'], 'Benzer yaşam koşulları ve ortak değerlere dayanan yakın komşuluk ilişkileri Durkheim\'ın mekanik dayanışmasına uygun düşer.'),
  ('Göçebe Türk boylarında toplumsal örgütlenme aileden başlayarak genişleyen bir yapı gösterir. Hangi sıralama küçükten büyüğe doğru verilmiştir?', 'Oğuş, urug, boy, budun', ['Budun, boy, urug, oğuş', 'Boy, oğuş, budun ve urug', 'Urug, budun, oğuş, boy'], 'Eski Türklerde aile (oğuş) bir araya gelerek sülaleyi (urug), sülaleler boyu, boylar da budunu (millet) oluşturur.'),
  ('Bir sosyolog, aynı konuda bir uzman tarafından yönetilen 8-10 kişilik bir grubu bir araya getirip katılımcıların karşılıklı tartışmasını kaydediyor. Bu teknik hangisidir?', 'Odak grup görüşmesi', ['Boylamsal anket uygulaması', 'Belge ve arşiv taraması', 'Katılımsız yapılandırılmış gözlem'], 'Odak grup görüşmesinde küçük bir grup, bir moderatör eşliğinde belirli bir konuyu tartışır; etkileşimden doğan görüşler incelenir.'),
  ('Bir araştırmacı, insanlar ne kadar uzun süre okula giderse günlük haberleri o kadar sık izlediklerini öne sürüyor. Bu hipotezde bağımlı değişken hangisidir?', 'Haber izleme sıklığı', ['Okulda geçirilen toplam süre', 'Haber kanallarının sayısı', 'Araştırmanın yapıldığı yıl'], 'Hipotezde etkilenen, yani sonuç olarak ele alınan değişken haber izleme sıklığıdır; okulda geçirilen süre ise bağımsız değişkendir.'),
  ('Araştırmaya katılan kişilerin kimliklerinin gizli tutulması ve katılımın gönüllü olması hangi ilkeyle ilgilidir?', 'Araştırma etiği', ['Örneklem büyüklüğü', 'Hipotez kurma', 'Verilerin sayısallaştırılması'], 'Sosyal araştırmalarda bilgilendirilmiş onam, gönüllülük ve gizlilik temel etik ilkelerdir.'),
  ('"Bir öğrenci kendini başarısız olarak tanımlayan öğretmen ve arkadaş tepkileri sonucunda gerçekten derslerden uzaklaşabilir." Bu açıklama hangi kuramsal yaklaşıma daha yakındır?', 'Sembolik etkileşimcilik', ['Yapısal işlevselcilik', 'Dünya sistemleri kuramı', 'Tarihsel materyalizm'], 'Başkalarının tepkileri ve yüklenen anlamlarla benliğin biçimlenmesi, sembolik etkileşimciliğin temel savıdır.'),
  ('Feminist kuramın sosyolojiye kazandırdığı temel bakış açısı hangisidir?', 'Toplumsal cinsiyetin, kadın ve erkeğe yüklenen rollerin toplumsal olarak kurulduğu', ['Cinsiyet rollerinin tümüyle biyolojik olarak belirlendiği', 'Toplumsal kurumların cinsiyetle hiçbir ilişkisinin olmadığı', 'Aile içi ilişkilerin sosyolojinin konusu olmadığı'], 'Feminist kuram, kadınlık ve erkeklikle ilgili beklentilerin kültürel olarak üretildiğini ve toplumsal eşitsizliklerle bağlantılı olduğunu vurgular.'),
  ('Toplumsal etkileşimi, bireylerin maliyet ve ödülleri karşılaştırdığı bir alışveriş gibi ele alan yaklaşım hangisidir?', 'Toplumsal değişim (alışveriş) kuramı', ['Yapısal işlevselcilik ve AGIL şeması', 'Etiketleme kuramı', 'Dünya sistemleri kuramı'], 'George Homans ve Peter Blau gibi sosyologların geliştirdiği bu yaklaşıma göre bireyler ilişkilerinde ödülü en çoklaştırmaya, maliyeti en aza indirmeye çalışır.'),
  ('Bir sosyolog "Neden kentlerde boşanma oranı köylere göre daha yüksektir?" sorusunu soruyorsa sosyolojinin hangi amacına yönelmiştir?', 'Toplumsal olayların nedenlerini açıklamaya', ['Toplum için kesin ahlaki kurallar koymaya ve uygulatmaya', 'Bireysel ilişkileri yargılamaya', 'Yalnızca olayları sayıya dökmeye'], 'Sosyoloji olayları betimlemenin ötesinde, nedenleri ve aralarındaki ilişkileri açıklamaya çalışır.'),
  ('Bir toplumda bir köy imamının, bir devlet hastanesindeki başhekimin ya da bir yazarın saygınlığının farklı olması, statülerin hangi boyutunu yansıtır?', 'Toplumsal saygınlık (prestij) boyutunu', ['Statülerin tümünün eşit olduğunu', 'Rol çatışmasının her durumda kaçınılmaz olduğunu', 'Statülerin doğuştan gelmesini'], 'Statüler toplum tarafından farklı ölçülerde saygın görülür; bu saygınlık mesleğe, kültüre ve döneme göre değişir.'),
  ('Bir futbolcunun sakatlanarak oyunu bırakmasından sonra da toplumda hâlâ "eski milli futbolcu" olarak anılması hangi kavramla açıklanabilir?', 'Ana statünün kalıcı etkisi', ['Statü kümesinin ortadan kalkması', 'Rol geriliminin artması', 'Verilmiş statünün kazanılması'], 'Toplumun kişiyi en çok tanıdığı statü, o statü sona erse bile kişinin toplumsal kimliğini belirlemeye devam edebilir.'),
  ('Bir lokantada yemekten sonra garsona bahşiş bırakılması, birçok toplumda yazılı bir kural olmadığı halde uyulan bir davranıştır. Bu davranış hangi tür norma girer?', 'Âdet ya da görenek', ['Hukuk kuralı ve yasal yükümlülük', 'Dinsel emir', 'Ahlak yasası'], 'Yazılı olmayan, uyulmadığında hafif tepki gören ve alışkanlığa dayanan davranış kuralları âdet ya da görenektir.'),
  ('Bir toplumda modanın sürekli değişmesine karşın geleneklerin uzun süre korunması hangi farkı ortaya koyar?', 'Modanın kısa ömürlü, geleneğin süreklilik gösteren bir norm olması', ['Modanın yazılı, geleneğin yazısız olması', 'Geleneğin yalnızca kentlerde, modanın köylerde görülmesi', 'İkisinin de devlet yaptırımına dayanması'], 'Moda yenilik arayışına dayanır ve hızla değişir; gelenek ise geçmişe dayanır ve kuşaklar boyunca sürer.'),
  ('Bir toplumda artık işlevini yitirmiş olmasına karşın sürdürülen kültürel öğelere ne ad verilir?', 'Kültürel kalıntı', ['Kültürel yenilik ve icat', 'Karşıt kültür hareketi', 'Kültürel evrensel öğe'], 'Kültürel kalıntılar, ortaya çıktıkları koşullar ortadan kalktığı halde süren uygulamalardır; örneğin ceketlerin kol düğmeleri.'),
  ('Kültürün "toplumsal" olması özelliği ne anlama gelir?', 'Kültürün bireysel değil, toplum üyelerince paylaşılan bir birikim olması', ['Kültürün yalnızca devlet kurumlarınca üretilmesi', 'Kültürün bireyin kendi başına yarattığı bir şey olması', 'Kültürün yalnızca kentlerde var olması'], 'Kültür bir bireyin değil, toplumun ortak ürünüdür; üyeler arasında paylaşılır ve onları birbirine bağlar.'),
  ('Bir toplumda şalvarın yerini zamanla pantolonun alması ama bayram ziyaretlerinin aynen sürmesi kültürün hangi özelliğini gösterir?', 'Kültür öğelerinin farklı hızlarda değişebildiğini', ['Kültürün hiçbir zaman değişmediğini', 'Maddi kültürün hiç değişmediğini', 'Manevi kültürün her zaman ve her yerde daha hızlı değiştiğini'], 'Giyim gibi maddi öğeler hızla değişebilirken bayramlaşma gibi manevi öğeler daha uzun süre korunabilir.'),
  ('Büyük kentlerde orta sınıfın kent merkezinden çevredeki yeni yerleşim alanlarına taşınmasına ne ad verilir?', 'Banliyöleşme', ['Gecekondulaşma', 'Soylulaştırma', 'Kırsallaşma'], 'Banliyöleşme, nüfusun ve konutların kent merkezinden çevredeki banliyölere doğru yayılmasıdır.'),
  ('Tabakalaşmanın "evrensel" olduğu, ama biçiminin "göreli" olduğu yargısı neyi anlatır?', 'Eşitsizlik her toplumda bulunur, ölçütleri toplumlara göre değişir', ['Hiçbir toplumda eşitsizlik görülmez', 'Bütün toplumlarda kast sistemi vardır', 'Tabakalaşma yalnızca sanayi toplumlarında bulunur'], 'Bilinen bütün karmaşık toplumlarda bir tür tabakalaşma görülür; ancak hangi ölçütün önemli sayıldığı ve geçişlerin ne kadar açık olduğu farklıdır.'),
  ('Kapalı tabakalaşma sistemlerinde toplumsal hareketliliğin düşük olmasının temel nedeni hangisidir?', 'Konumların büyük ölçüde doğuştan belirlenmesi', ['Eğitimin herkese açık olması', 'Ekonominin hizmet sektörüne dayanması', 'Kentleşmenin çok hızlı olması'], 'Kast gibi kapalı sistemlerde birey doğduğu konumda kalır; yükselmeyi sağlayacak meşru yollar çok sınırlıdır.'),
  ('Din sosyolojisinde dinin "anlam verme" işlevi en iyi hangi örnekle açıklanır?', 'İnsanların ölüm ve acı gibi deneyimlere bir açıklama bulması', ['Bir ülkenin ihracat gelirlerinin artması', 'Kentlerin altyapısının yenilenmesi', 'Bir okulun ders programının belirlenmesi'], 'Din, insanlara yaşamın, ölümün ve acının anlamına ilişkin açıklamalar sunarak belirsizlikle başa çıkmalarına yardımcı olur.'),
  ('Siyasal katılımın sosyolojik açıdan önemi en iyi hangi seçenekte ifade edilmiştir?', 'Yurttaşların ortak kararları etkileme olanağını göstermesi', ['Yalnızca yöneticilerin kendi aralarında karar almasını sağlaması', 'Toplumsal grupların siyasetten tamamen uzaklaşmasını sağlaması', 'Ekonomik üretimi doğrudan artırması'], 'Seçimlere katılma, dernek ve partilere üyelik gibi etkinlikler bireylerin toplumsal kararlar üzerindeki etkisini yansıtır.'),
  ('Bir haber kanalının aynı olayı belirli bir bakış açısını öne çıkararak sunması ve izleyicinin olayı bu çerçeveden yorumlaması hangi kavramla açıklanır?', 'Çerçeveleme', ['Kültürlenme', 'Asimilasyon', 'Yatay hareketlilik'], 'Çerçeveleme, medyanın bir olayın bazı yönlerini vurgulayıp bazılarını geri planda bırakarak izleyicinin yorumunu yönlendirmesidir.'),
  ('Medyada belirli grupların sürekli olumsuz rollerde gösterilmesinin toplumsal sonucu ne olabilir?', 'Bu gruplar hakkında kalıp yargıların güçlenmesi', ['Gruplar arasındaki önyargıların tamamen ortadan kalkması', 'Medyanın toplumu hiç etkilememesi', 'Toplumsal hareketliliğin her durumda artması'], 'Tekrarlanan olumsuz temsiller izleyicilerin bu gruplara ilişkin genellemelerini pekiştirerek önyargı ve ayrımcılığı besleyebilir.'),
  ('1.000 kişilik bir kasabada bir yılda 30 kişi dışarıdan gelip yerleşmiş, 50 kişi ise başka yerlere göç etmiştir. Bu kasabanın net göç hızı binde kaçtır?', '-20', ['20', '80', '-80'], 'Net göç, gelen göç ile giden göç arasındaki farktır: 30 - 50 = -20; nüfus 1.000 olduğundan net göç hızı binde -20\'dir.'),
  ('Bir ülkenin nüfus piramidinin tabanının geniş, tepesinin dar olması neyi gösterir?', 'Doğum oranının yüksek, ortalama ömrün görece kısa olduğunu', ['Nüfusun hızla yaşlandığını', 'Doğum oranının çok düşük olduğunu', 'Ülkenin yoğun göç aldığını'], 'Geniş taban çok sayıda çocuk ve genç nüfusa, dar tepe ise az sayıda yaşlıya işaret eder; bu genç ve hızlı büyüyen nüfusların tipik görünümüdür.'),
  ('Toplumsal kontrolün aşırı sert ve kapsayıcı olduğu bir toplumda hangi sorun ortaya çıkabilir?', 'Yaratıcılığın ve yeniliğin bastırılması', ['Toplumsal düzenin tamamen ortadan kalkması', 'Normların hiç bulunmaması', 'Bireylerin bütün kuralları özgürce değiştirebilmesi'], 'Kontrol düzeni sağlar; ancak aşırı denetim bireysel farklılığı, eleştiriyi ve yeniliği bastırarak toplumsal gelişmeyi engelleyebilir.'),
  ('Marx\'a göre kapitalizmde işçinin emeğinin karşılığı olan ücret ile ürettiği değer arasındaki farka ne ad verilir?', 'Artı değer', ['Kullanım değeri', 'Kültürel sermaye', 'Toplumsal sermaye'], 'Artı değer, işçinin ürettiği değerin ücret olarak ödenen kısmını aşan bölümüdür; Marx\'a göre kapitalistin kârının kaynağıdır.'),
  ('İbn Haldun\'un tarihçilere yönelttiği eleştirinin özü hangisidir?', 'Olayları neden-sonuç ve toplumsal koşullarla sınamadan aktarmaları', ['Tarih yazımında hiç kaynak kullanmamaları', 'Yalnızca ekonomik olayları yazmaları', 'Olayları her zaman doğru biçimde açıklamaları'], 'İbn Haldun, tarihçilerin rivayetleri toplumsal yaşamın doğasına uygun olup olmadığını sorgulamadan aktardığını ve bu yüzden yanılgılara düştüğünü savunmuştur.'),
  ('Osmanlı\'da devletin toprağın mülkiyetini elinde tutup gelirini askerî hizmet karşılığında sipahilere bıraktığı düzen hangisidir?', 'Tımar sistemi', ['Lonca sistemi', 'Vakıf sistemi', 'İltizam sistemi'], 'Tımar sisteminde toprağın mülkiyeti devlete aitti; sipahi, belirlenen gelir karşılığında asker yetiştirir ve bölgenin güvenliğini sağlardı.'),
  ('Osmanlı tımar sisteminin Avrupa feodalizminden ayrılan sosyolojik özelliği hangisidir?', 'Toprak mülkiyetinin devlette kalması ve sipahinin toprağın sahibi olmaması', ['Toprağın sipahiye miras olarak kesin biçimde geçmesi', 'Köylülerin hiçbir vergi ödememesi', 'Merkezi otoritenin hiç bulunmaması'], 'Avrupa\'da toprak beyin mülküyken Osmanlı\'da toprak devletindi; bu durum merkezi otoriteyi güçlü tutuyordu.'),
  ('Geleneksel Türk köyünde düğün, cenaze ve hasat gibi olaylarda komşuların birbirine yardım etmesi en çok neyi gösterir?', 'Güçlü yüz yüze ilişkilere dayalı toplumsal dayanışmayı', ['Köyde işbölümünün çok ileri olduğunu', 'Bireyciliğin köyde egemen olduğunu', 'Köylülerin birbirini tanımadığını'], 'Küçük ve yakın ilişkilere dayalı topluluklarda yardımlaşma, ortak değerler ve karşılıklı yükümlülüklerle sürdürülür.'),
  ('Merton\'un uyum biçimlerinden, toplumun hem amaçlarını hem de araçlarını reddedip toplumdan çekilen evsiz ya da bağımlı bireylerin durumu hangisidir?', 'Geri çekilme', ['Yenilikçilik', 'Ritüelcilik', 'Uyumculuk'], 'Geri çekilmede birey kültürel hedefleri de meşru araçları da reddeder ve toplumsal yaşamın dışına çekilir.'),
  ('Bir ülkede yeni bir yasa ile köy okullarının kapatılıp öğrencilerin taşımalı eğitimle merkez okullara götürülmesi toplumsal yapının hangi öğesini doğrudan etkiler?', 'Eğitim kurumunun işleyişini', ['Bireylerin kan grubunu', 'Bölgenin iklim ve yağış koşullarını', 'Kişilerin doğum tarihini'], 'Okulların örgütlenme biçimindeki değişiklik, toplumsal yapının bir öğesi olan eğitim kurumunun işleyişini dönüştürür.'),
  ('Modernleşme kuramlarına yöneltilen başlıca eleştiri hangisidir?', 'Batı toplumlarının deneyimini bütün toplumlar için tek model sayması', ['Toplumsal değişmeyi hiç ele almaması', 'Sanayileşmeyi tamamen görmezden gelmesi', 'Yalnızca köy toplumlarını incelemesi'], 'Eleştirmenler, modernleşme kuramlarının Batı\'yı evrensel bir ölçüt olarak alıp farklı tarihsel yolları göz ardı ettiğini ileri sürer.'),
  ('Gelişmekte olan ülkelerin geri kalmışlığını iç etkenlerden çok gelişmiş ülkelere ekonomik bağımlılıkla açıklayan yaklaşım hangisidir?', 'Bağımlılık kuramı', ['Modernleşme kuramı', 'Sembolik etkileşimcilik', 'Organizmacı yaklaşım'], 'Bağımlılık kuramına göre çevre ülkeler hammadde sağlayıcısı olarak merkez ülkelere bağımlı kılınmış ve bu durum kalkınmalarını engellemiştir.'),
  ('Bir ülkede yerel bir şarkının internette milyonlarca kez dinlenerek dünyanın farklı ülkelerinde tanınması hangi süreci örnekler?', 'Kültürel küreselleşme', ['Kırsallaşma', 'Kültürel kalıntı ve artık öğe', 'Kast sistemi'], 'Küresel iletişim ağları yerel kültürel ürünlerin de dünya ölçeğinde yayılmasını mümkün kılar.'),
  ('Toplumsal değişmenin tek bir etkenle açıklanamayacağı görüşünün en güçlü dayanağı hangisidir?', 'Teknoloji, ekonomi, nüfus ve fikirlerin birbirini karşılıklı etkilemesi', ['Toplumların hiç değişmemesi', 'Değişmenin yalnızca coğrafyadan kaynaklanması', 'Değişmenin yalnızca bireysel kararlarla olması'], 'Toplumsal değişmede teknolojik, ekonomik, demografik ve kültürel etkenler iç içe geçer; bu yüzden tek nedenli açıklamalar yetersiz kalır.'),
  ('Bürokratik örgütlerde görevlerin ayrıntılı biçimde tanımlanmasının amacı hangisidir?', 'İşlerin uzmanlaşmış biçimde ve karışıklık olmadan yürütülmesi', ['Çalışanların istedikleri işi istedikleri zaman ve istedikleri biçimde yapması', 'Kişisel ilişkilerin kararları belirlemesi', 'Örgütün kurallarının sürekli değişmesi'], 'Görev tanımları işbölümü ve uzmanlaşmayı sağlar; herkesin sorumluluğu belli olduğundan iş düzenli yürür.'),
  ('Sosyolojide madde bağımlılığının yalnızca bireysel bir zayıflık olarak görülmemesinin nedeni hangisidir?', 'Bağımlılığın yaygınlığının işsizlik, çevre ve erişim gibi toplumsal etkenlerle ilişkili olması', ['Bağımlılığın hiçbir zaman bireyleri etkilememesi', 'Bağımlılığın yalnızca kalıtımla geçmesi', 'Bağımlılığın yasalarla tamamen önlenmiş olması'], 'Bağımlılığın görülme sıklığı toplumsal koşullara göre değişir; bu da sorunun toplumsal boyutunu gösterir.'),
  ('Cooley\'in ayna benlik sürecindeki üç aşama hangi sırayla verilmiştir?', 'Başkalarına nasıl göründüğünü hayal etme, onların yargısını yorumlama, kendine ilişkin duygu geliştirme', ['Kendine ilişkin duygu geliştirme, başkalarını taklit etme, kuralları öğrenme', 'Kuralları öğrenme, oyun oynama, genelleştirilmiş ötekini kavrama', 'Başkalarını yargılama, onlardan uzaklaşma, yalnız kalma'], 'Cooley\'e göre birey önce başkalarına nasıl göründüğünü hayal eder, sonra onların bu görüntüyü nasıl değerlendirdiğini yorumlar ve buna göre gurur ya da utanç gibi bir benlik duygusu geliştirir.'),
  ('Bir konserde seyircilerin şarkılara hep birlikte eşlik etmesi ve coşkularını dışa vurması Blumer\'e göre hangi kalabalık türüdür?', 'Dışavurumcu kalabalık', ['Rastlantısal kalabalık', 'Etkin (eylemci) kalabalık', 'Geleneksel kalabalık'], 'Dışavurumcu kalabalıkta insanlar duygularını açığa vurmak amacıyla bir araya gelir; konser ve festivaller buna örnektir.'),
  ('"Gücü bilgiyle ilişkilendiren" ve hapishane, okul, hastane gibi kurumlarda disiplinin tarihsel gelişimini inceleyen Fransız düşünür kimdir?', 'Michel Foucault', ['Auguste Comte', 'Gabriel Tarde', 'Emile Durkheim'], 'Foucault, Hapishanenin Doğuşu adlı eserinde modern kurumların bedenleri ve davranışları disipline ettiğini ve iktidarın bilgiyle iç içe işlediğini savunmuştur.'),
  ('Toplumsal etkileşimin "biçimlerini" (rekabet, çatışma, üstünlük gibi) içeriklerinden ayırarak inceleyen biçimsel sosyolojinin kurucusu sayılan Alman sosyolog kimdir?', 'Georg Simmel', ['Karl Marx', 'Talcott Parsons', 'Herbert Spencer'], 'Simmel, farklı içerikteki ilişkilerde ortak etkileşim biçimlerinin bulunduğunu ve sosyolojinin bu biçimleri incelemesi gerektiğini savunmuştur.'),
  ('Bir toplumsal kurumun "kurumsallaşmış" sayılabilmesi için hangi koşul gereklidir?', 'Davranış kalıplarının yerleşik, beklenebilir ve kuşaktan kuşağa aktarılır hale gelmesi', ['Tek bir kişinin bir kez yaptığı bir davranış olması', 'Yalnızca bir gün süren bir etkinlik olması', 'Hiçbir kurala ya da role dayanmaması'], 'Kurumsallaşma, bir ihtiyaca yönelik davranışların zamanla kurallar, roller ve beklentiler halinde kalıcılaşmasıdır.'),
  ('Eşlerin benzer eğitim düzeyi, gelir ve toplumsal kökenden gelme eğilimine sosyolojide ne ad verilir?', 'Homogami (benzer eşlilik)', ['Poliandri (çok kocalılık)', 'Levirat', 'Sororat'], 'Homogami, insanların kendilerine toplumsal özellikler bakımından benzeyen kişilerle evlenme eğilimidir; bu durum tabakalaşmanın sürmesine de katkı yapar.'),
  ('Göçebe çoban toplumlarını tarım toplumlarından ayıran temel özellik hangisidir?', 'Geçimin hayvan sürülerine dayanması ve otlak arayışıyla yer değiştirilmesi', ['Fabrikalarda seri üretim yapılması', 'Bilgi teknolojilerinin ekonomiye egemen olması', 'Yerleşik köylerde saban tarımı yapılması'], 'Çoban toplumları sürüleri için otlak arar ve mevsimlere göre yer değiştirir; tarım toplumları ise toprağa bağlı yerleşik yaşar.'),
  ('İş arkadaşlarının hafta sonları birlikte vakit geçirerek zamanla yakın dost olmaları grup türleri açısından neyi gösterir?', 'İkincil grup ilişkilerinden birincil grup ilişkilerinin doğabileceğini', ['Birincil grupların hiçbir zaman oluşamayacağını', 'İş yerinin bir toplumsal kategori olduğunu', 'Grupların hiç değişmediğini'], 'Amaca dönük ikincil gruplar içinde zamanla sıcak ve kişisel birincil ilişkiler gelişebilir.'),
  ('Bir toplumda katı kurallar ve aşırı denetim nedeniyle bireyin geleceğinin tamamen kapatıldığını hissetmesiyle ortaya çıkan intihar türü Durkheim\'ın sınıflamasında hangisidir?', 'Kadercil (fatalistik) intihar', ['Anomik intihar', 'Egoist intihar', 'Diğerkâm intihar'], 'Kadercil intihar, normların aşırı baskıcı olduğu, bireyin hiçbir çıkış yolu görmediği durumlarda ortaya çıkar; anomik intiharın karşıt kutbudur.'),
  ('Weber\'in din sosyolojisi çalışmalarında incelediği dünya dinleri arasında Çin\'in dinlerini ele aldığı eser hangisidir?', 'Çin\'in Dini: Konfüçyüsçülük ve Taoizm', ['Dinsel Yaşamın İlkel Biçimleri', 'Toplumsal İşbölümü Üzerine', 'Sosyolojik Yöntemin Kuralları'], 'Weber Çin\'in Dini adlı eserinde Konfüçyüsçülük ve Taoizmin ekonomik ahlakla ilişkisini incelemiştir; diğer üç eser Durkheim\'a aittir.'),
  ('Ulaşılması güç bir grubu, örneğin kayıt dışı çalışan göçmenleri inceleyen bir araştırmacının her görüşmeciden tanıdığı başka bir kişiye ulaşmak için yardım istemesi hangi tekniktir?', 'Kartopu örneklemesi', ['Tabakalı örnekleme', 'Basit rastgele örnekleme', 'Sistematik örnekleme'], 'Kartopu örneklemesinde her katılımcı araştırmacıyı yeni katılımcılara yönlendirir; gizli ya da dağınık gruplara ulaşmakta kullanılır.'),
  ('Bir müzede sergilenen eski el yazmaları ile bu yazmalarda anlatılan halk masalları kültürün hangi öğeleri olarak sınıflandırılır?', 'Maddi ve manevi kültür öğeleri', ['Yalnızca maddi kültür öğeleri', 'Karşıt kültür öğeleri', 'Alt kültür öğeleri'], 'El yazması somut bir nesne olarak maddi kültüre, içindeki masallar ise anlatı ve inanç olarak manevi kültüre girer.'),
  ('Dil ile kültür arasındaki ilişkiye en uygun açıklama hangisidir?', 'Dil hem kültürün bir parçası hem de onu aktaran temel araçtır', ['Dil kültürden tamamen bağımsız bir sistemdir', 'Kültür dil olmadan da aynı biçimde aktarılabilir', 'Dil yalnızca maddi kültürün bir öğesidir'], 'Dil, kültürün manevi öğelerinden biridir ve aynı zamanda bilgi, değer ve deneyimlerin kuşaktan kuşağa aktarılmasını sağlar.'),
  ('Ailenin "koruyucu işlevi" ile kastedilen hangisidir?', 'Üyelerin bakımını, güvenliğini ve barınmasını sağlamak', ['Ülkenin dış politikasını belirlemek', 'Kentlerin altyapısını kurmak', 'Fiyatları ve ücretleri düzenlemek'], 'Aile, özellikle çocukların, yaşlıların ve hastaların bakımını üstlenerek üyelerini koruyan bir kurumdur.'),
  ('Bir köyde muhtarın resmi yetkisi olduğu halde köylülerin önemli kararlarda daha çok saygın bir yaşlıya danışması Weber\'in kavramlarıyla nasıl açıklanır?', 'Yasal-ussal otoritenin yanında geleneksel otoritenin de etkili olması', ['Karizmanın rutinleşmesi', 'Bürokratik otoritenin tek başına egemen olması', 'Oligarşinin tunç yasası'], 'Muhtar yasal yetkisini makamdan alırken saygın yaşlının etkisi gelenek ve saygınlığa dayanır; iki otorite türü bir arada işler.'),
  ('Bir ülkede doğu illerinden batı illerine yoğun göç yaşanmasının gönderen bölge açısından olası sonucu hangisidir?', 'Genç ve üretken nüfusun azalması', ['Bölgenin nüfusunun hızla gençleşmesi', 'Bölgede kentleşmenin hızlanması', 'Bölgedeki sanayi tesislerinin çoğalması'], 'Göç genellikle genç ve çalışma çağındaki nüfusu harekete geçirdiğinden, gönderen bölgelerde yaşlı ve bağımlı nüfusun payı artar.'),
];
